import { GoogleGenAI, Type } from "@google/genai";
import { InquiryAnalysis, ManagerSearchResult } from "../types";

// Initialize the client. 
// Note: In a production app, ensure API keys are secured via backend proxies.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

// 1. Inquiry Analysis
export const analyzePropertyRequirement = async (
  formData: any
): Promise<InquiryAnalysis> => {
  const prompt = `
    Analyze this property inquiry for a property management company.

    Data:
    City: ${formData.city}
    Units: ${formData.units}
    Type: ${formData.propertyType}
    Services: ${formData.servicesNeeded.join(", ")}
    Age: ${formData.buildingAge}
    Condition: ${formData.condition}
    Description: ${formData.description}

    Provide a summary, list of key requirements, and estimate the management effort (Low/Medium/High).
    Also suggest some categorization tags.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            keyRequirements: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
            },
            estimatedEffort: {
              type: Type.STRING,
              enum: ["Low", "Medium", "High"],
            },
            recommendedTags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
            },
          },
          required: ["summary", "keyRequirements", "estimatedEffort", "recommendedTags"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text) as InquiryAnalysis;
  } catch (error) {
    console.error("AI Analysis Error:", error);
    // Fallback if API fails or key is missing
    return {
      summary: "Could not analyze property at this time.",
      keyRequirements: ["Review manually"],
      estimatedEffort: "Medium",
      recommendedTags: ["Pending"],
    };
  }
};

// 2. Manager Search with Grounding
export const searchPropertyManagers = async (city: string): Promise<ManagerSearchResult> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // Use Pro for better reasoning/search
      contents: `Find 3-5 top-rated property management companies (Hausverwaltung) in ${city}, Germany. Summarize why they are recommended.`,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "No results found.";

    // Extract grounding chunks
    const sources: any[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web?.uri && chunk.web?.title) {
          sources.push({
            title: chunk.web.title,
            url: chunk.web.uri,
          });
        }
      });
    }

    // Deduplicate sources based on URL
    const uniqueSources = Array.from(new Map(sources.map(s => [s.url, s])).values());

    return {
      introText: text,
      sources: uniqueSources,
    };
  } catch (error) {
    console.error("Search Error:", error);
    return {
      introText: "Search functionality is currently unavailable. Please check your API configuration.",
      sources: [],
    };
  }
};

// 3. AI Advisor Chat
export const getAIAdvisorResponse = async (history: {role: string, parts: {text: string}[]}[], message: string) => {
  try {
    const chat = ai.chats.create({
      model: "gemini-3-flash-preview",
      config: {
        systemInstruction: "You are an expert in German property management law (WEG-Reform, Rental Law). Provide concise, professional advice to property owners. Disclaimer: You are an AI, not a lawyer.",
      },
      history: history
    });

    const result = await chat.sendMessage({ message });
    return result.text || "I'm sorry, I couldn't generate a response.";
  } catch (error) {
    console.error("Chat Error:", error);
    return "I am currently having trouble connecting to the service. Please try again later.";
  }
};

import { Inquiry, ForumThread, Message, User } from "../types";

// Mock Data Storage using LocalStorage to persist across refreshes
const STORAGE_KEYS = {
  INQUIRIES: 'hausmatch_inquiries',
  THREADS: 'hausmatch_threads',
  MESSAGES: 'hausmatch_messages',
};

// Helper to simulate network delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- Inquiries ---

export const getInquiries = async (): Promise<Inquiry[]> => {
  await delay(500);
  const data = localStorage.getItem(STORAGE_KEYS.INQUIRIES);
  return data ? JSON.parse(data) : [];
};

export const createInquiry = async (inquiry: Omit<Inquiry, 'id' | 'createdAt'>): Promise<Inquiry> => {
  await delay(800);
  const inquiries = await getInquiries();
  const newInquiry: Inquiry = {
    ...inquiry,
    id: Math.random().toString(36).substr(2, 9),
    createdAt: Date.now(),
  };
  inquiries.unshift(newInquiry);
  localStorage.setItem(STORAGE_KEYS.INQUIRIES, JSON.stringify(inquiries));
  return newInquiry;
};

export const updateInquiryStatus = async (id: string, status: 'contacted' | 'archived') => {
  const inquiries = await getInquiries();
  const updated = inquiries.map(i => i.id === id ? { ...i, status } : i);
  localStorage.setItem(STORAGE_KEYS.INQUIRIES, JSON.stringify(updated));
};

// --- Forum ---

const MOCK_THREADS: ForumThread[] = [
  { id: '1', title: 'WEG Reform 2024 updates?', author: 'ManagerHans', category: 'Legal', content: 'Has anyone started implementing the new digital meeting protocols?', replies: 12, views: 340, createdAt: Date.now() - 86400000 },
  { id: '2', title: 'Best software for accounting?', author: 'PropTechLisa', category: 'Tech', content: 'Looking for alternatives to the legacy systems.', replies: 5, views: 120, createdAt: Date.now() - 172800000 },
];

export const getForumThreads = async (): Promise<ForumThread[]> => {
  await delay(300);
  const data = localStorage.getItem(STORAGE_KEYS.THREADS);
  if (!data) {
    localStorage.setItem(STORAGE_KEYS.THREADS, JSON.stringify(MOCK_THREADS));
    return MOCK_THREADS;
  }
  return JSON.parse(data);
};

export const createThread = async (thread: Omit<ForumThread, 'id' | 'replies' | 'views' | 'createdAt'>) => {
  await delay(400);
  const threads = await getForumThreads();
  const newThread: ForumThread = {
    ...thread,
    id: Math.random().toString(36).substr(2, 9),
    replies: 0,
    views: 0,
    createdAt: Date.now(),
  };
  threads.unshift(newThread);
  localStorage.setItem(STORAGE_KEYS.THREADS, JSON.stringify(threads));
};

// --- Messaging ---

export const getMessages = async (userId: string): Promise<Message[]> => {
  await delay(300);
  const data = localStorage.getItem(STORAGE_KEYS.MESSAGES);
  const messages: Message[] = data ? JSON.parse(data) : [];
  return messages.filter(m => m.receiverId === userId || m.senderId === userId).sort((a,b) => b.timestamp - a.timestamp);
};

export const sendMessage = async (msg: Omit<Message, 'id' | 'timestamp' | 'isRead'>) => {
  await delay(400);
  const data = localStorage.getItem(STORAGE_KEYS.MESSAGES);
  const messages: Message[] = data ? JSON.parse(data) : [];
  const newMessage: Message = {
    ...msg,
    id: Math.random().toString(36).substr(2, 9),
    isRead: false,
    timestamp: Date.now(),
  };
  messages.push(newMessage);
  localStorage.setItem(STORAGE_KEYS.MESSAGES, JSON.stringify(messages));

  // Simulate Notification if supported
  if ('Notification' in window && Notification.permission === 'granted') {
    new Notification(`New Message from ${msg.senderName}`, { body: msg.subject });
  }
};

