export default Login;

import React, { useState, useContext, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { AuthContext } from '../App';
import { analyzePropertyRequirement, getAIAdvisorResponse } from '../services/geminiService';
import { createInquiry } from '../services/dataService';
import { Inquiry } from '../types';

const STEPS = ['Location', 'Services', 'Technical', 'Review'];

const Wizard = () => {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    city: searchParams.get('city') || '',
    units: 1,
    propertyType: 'WEG',
    servicesNeeded: [] as string[],
    buildingAge: '',
    condition: 'Good',
    description: '',
  });

  // Chat Advisor State
  const [chatOpen, setChatOpen] = useState(false);
  const [chatHistory, setChatHistory] = useState<{role: string, parts: {text: string}[]}[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);

  const handleNext = () => setStep(p => p + 1);
  const handleBack = () => setStep(p => p - 1);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      // 1. Analyze with AI
      const analysis = await analyzePropertyRequirement(formData);

      // 2. Save to mock DB
      await createInquiry({
        ...formData,
        ownerId: user?.id || 'guest',
        ownerName: user?.name || 'Guest User',
        ownerEmail: user?.email || 'guest@example.com',
        status: 'new',
        aiAnalysis: analysis,
        units: Number(formData.units),
        propertyType: formData.propertyType as any,
      });

      // 3. Navigate to results (pass city for search)
      navigate(`/search-results?city=${encodeURIComponent(formData.city)}`);
    } catch (e) {
      console.error(e);
      alert('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatLoading(true);

    // Optimistic UI
    const newHistory = [...chatHistory, { role: 'user', parts: [{ text: userMsg }] }];
    setChatHistory(newHistory);

    const aiResponse = await getAIAdvisorResponse(newHistory, userMsg);

    setChatHistory(prev => [...prev, { role: 'model', parts: [{ text: aiResponse }] }]);
    setChatLoading(false);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12 flex gap-8">
      {/* Main Wizard */}
      <div className="flex-1">
        <div className="mb-8">
          <nav aria-label="Progress">
            <ol className="flex items-center">
              {STEPS.map((s, i) => (
                <li key={s} className={`relative ${i !== STEPS.length - 1 ? 'pr-8 sm:pr-20' : ''}`}>
                  <div className="flex items-center">
                    <div className={`h-8 w-8 rounded-full flex items-center justify-center ${i <= step ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                      {i + 1}
                    </div>
                    <span className="ml-4 text-sm font-medium text-slate-900 hidden sm:block">{s}</span>
                  </div>
                  {i !== STEPS.length - 1 && (
                    <div className={`absolute top-4 left-0 w-full h-0.5 -ml-px ${i < step ? 'bg-indigo-600' : 'bg-slate-200'}`} aria-hidden="true" />
                  )}
                </li>
              ))}
            </ol>
          </nav>
        </div>

        <div className="bg-white shadow rounded-2xl p-8 min-h-[400px]">
          {step === 0 && (
            <div className="space-y-6">
              <h2 className="text-2xl font-bold">Property Location</h2>
              <div>
                <label className="block text-sm font-medium text-slate-700">City</label>
                <input
                  type="text"
                  value={formData.city}
                  onChange={e => setFormData({...formData, city: e.target.value})}
                  className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-3 border"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700">Number of Units</label>
                <input
                  type="number"
                  value={formData.units}
                  onChange={e => setFormData({...formData, units: Number(e.target.value)})}
                  className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-3 border"
                />
              </div>
            </div>
          )}

          {step === 1 && (
             <div className="space-y-6">
               <h2 className="text-2xl font-bold">Services Required</h2>
               <div>
                  <label className="block text-sm font-medium text-slate-700 mb-2">Property Type</label>
                  <select 
                    value={formData.propertyType}
                    onChange={e => setFormData({...formData, propertyType: e.target.value})}
                    className="block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-3 border"
                  >
                    <option value="WEG">WEG (Homeowners Association)</option>
                    <option value="Rental">Rental House (Mietshaus)</option>
                    <option value="Commercial">Commercial</option>
                  </select>
               </div>
               <div>
                 <label className="block text-sm font-medium text-slate-700 mb-2">Specific Needs</label>
                 <div className="grid grid-cols-2 gap-3">
                   {['Accounting', 'Maintenance', 'Cleaning', 'Legal Representation', 'Tenant Search'].map(s => (
                     <label key={s} className="flex items-center space-x-3 p-3 border rounded-lg cursor-pointer hover:bg-slate-50">
                       <input 
                          type="checkbox" 
                          checked={formData.servicesNeeded.includes(s)}
                          onChange={e => {
                            const current = formData.servicesNeeded;
                            setFormData({
                              ...formData,
                              servicesNeeded: current.includes(s) ? current.filter(x => x !== s) : [...current, s]
                            })
                          }}
                          className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                       />
                       <span className="text-slate-700">{s}</span>
                     </label>
                   ))}
                 </div>
               </div>
             </div>
          )}

          {step === 2 && (
             <div className="space-y-6">
              <h2 className="text-2xl font-bold">Technical Details</h2>
              <div>
                <label className="block text-sm font-medium text-slate-700">Building Age (Year built)</label>
                <input
                  type="text"
                  value={formData.buildingAge}
                  onChange={e => setFormData({...formData, buildingAge: e.target.value})}
                  className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-3 border"
                  placeholder="e.g. 1985"
                />
              </div>
               <div>
                <label className="block text-sm font-medium text-slate-700">Overall Condition</label>
                <select
                  value={formData.condition}
                  onChange={e => setFormData({...formData, condition: e.target.value})}
                  className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-3 border"
                >
                  <option>New / Excellent</option>
                  <option>Good</option>
                  <option>Needs Renovation</option>
                  <option>Critical</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700">Additional Notes</label>
                <textarea
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  rows={4}
                  className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-3 border"
                  placeholder="Describe any specific issues or requirements..."
                />
              </div>
             </div>
          )}

          {step === 3 && (
            <div className="space-y-6 text-center">
               <h2 className="text-2xl font-bold">Ready to Match?</h2>
               <p className="text-slate-600">
                 Our AI will now analyze your request and search for the best property managers in {formData.city}.
               </p>
               <div className="bg-slate-50 p-6 rounded-xl text-left text-sm text-slate-700">
                 <p><strong>City:</strong> {formData.city}</p>
                 <p><strong>Type:</strong> {formData.propertyType}</p>
                 <p><strong>Units:</strong> {formData.units}</p>
                 <p><strong>Services:</strong> {formData.servicesNeeded.join(', ') || 'General Management'}</p>
               </div>
            </div>
          )}

          {/* Controls */}
          <div className="mt-8 flex justify-between">
            {step > 0 ? (
              <button onClick={handleBack} className="px-6 py-2 border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50">
                Back
              </button>
            ) : <div />}

            {step < STEPS.length - 1 ? (
              <button onClick={handleNext} className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">
                Next
              </button>
            ) : (
              <button 
                onClick={handleSubmit} 
                disabled={loading}
                className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2"
              >
                {loading ? 'Analyzing...' : 'Find Matches'}
              </button>
            )}
          </div>
        </div>
      </div>

      {/* AI Side Panel */}
      <div className={`fixed bottom-4 right-4 z-40 flex flex-col items-end transition-all duration-300`}>
        {chatOpen && (
          <div className="bg-white w-80 h-96 shadow-2xl rounded-2xl border border-slate-200 flex flex-col mb-4 overflow-hidden">
             <div className="bg-indigo-600 p-3 text-white flex justify-between items-center">
               <span className="font-medium text-sm">AI Legal Advisor</span>
               <button onClick={() => setChatOpen(false)} className="text-white/80 hover:text-white">&times;</button>
             </div>
             <div className="flex-1 p-3 overflow-y-auto space-y-3 bg-slate-50">
               {chatHistory.length === 0 && (
                 <p className="text-xs text-center text-slate-400 mt-4">Ask me about WEG laws or property management contracts.</p>
               )}
               {chatHistory.map((msg, idx) => (
                 <div key={idx} className={`p-2 rounded-lg text-sm max-w-[85%] ${msg.role === 'user' ? 'bg-indigo-100 ml-auto text-indigo-900' : 'bg-white border mr-auto text-slate-800'}`}>
                   {msg.parts[0].text}
                 </div>
               ))}
               {chatLoading && <div className="text-xs text-slate-400 ml-2">Thinking...</div>}
             </div>
             <div className="p-3 bg-white border-t flex gap-2">
               <input 
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleChat()}
                placeholder="Ask a question..."
                className="flex-1 text-sm border rounded-full px-3 py-1 focus:ring-indigo-500 focus:border-indigo-500"
               />
               <button onClick={handleChat} disabled={chatLoading} className="text-indigo-600 hover:text-indigo-800">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
               </button>
             </div>
          </div>
        )}
        <button 
          onClick={() => setChatOpen(!chatOpen)}
          className="bg-indigo-600 hover:bg-indigo-700 text-white p-4 rounded-full shadow-lg flex items-center gap-2 transition-transform hover:scale-105"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          {!chatOpen && <span className="font-medium">Ask Advisor</span>}
        </button>
      </div>
    </div>
  );
};

export default Wizard;

import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { searchPropertyManagers } from '../services/geminiService';
import { ManagerSearchResult } from '../types';

const SearchResults = () => {
  const [searchParams] = useSearchParams();
  const city = searchParams.get('city') || 'Germany';
  const [result, setResult] = useState<ManagerSearchResult | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const data = await searchPropertyManagers(city);
      setResult(data);
      setLoading(false);
    };
    fetchData();
  }, [city]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
        <p className="text-slate-500 font-mono text-sm">Querying Google Search Grounding API...</p>
        <p className="text-slate-400 text-xs">Looking for top-rated managers in {city}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-slate-900">Recommended Property Managers</h1>
        <p className="text-slate-600 mt-2">Based on AI analysis of top-rated providers in {city}</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main AI Summary */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
            <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
              <span className="bg-indigo-100 text-indigo-700 p-1 rounded">✨</span> 
              AI Summary
            </h2>
            <div className="prose prose-slate max-w-none text-slate-700 leading-relaxed whitespace-pre-wrap">
              {result?.introText}
            </div>
          </div>
        </div>

        {/* Grounding Sources */}
        <div className="space-y-6">
          <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider">Verified Sources</h3>
          {result?.sources.length === 0 && <p className="text-slate-400 text-sm">No direct sources linked.</p>}
          {result?.sources.map((source, idx) => (
            <a 
              key={idx}
              href={source.url}
              target="_blank"
              rel="noopener noreferrer"
              className="block group bg-white p-4 rounded-xl shadow-sm border border-slate-200 hover:shadow-md hover:border-indigo-300 transition-all"
            >
              <div className="flex items-start justify-between">
                <div>
                  <h4 className="font-medium text-slate-900 group-hover:text-indigo-600 line-clamp-2">{source.title}</h4>
                  <p className="text-xs text-slate-500 mt-1 truncate">{source.url}</p>
                </div>
                <svg className="w-4 h-4 text-slate-400 group-hover:text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
              </div>
            </a>
          ))}

           <div className="mt-8 bg-blue-50 p-4 rounded-xl border border-blue-100">
            <h4 className="text-sm font-bold text-blue-900 mb-2">Next Steps</h4>
            <p className="text-sm text-blue-800">
              Your inquiry has been saved. Local managers will review your requirements and contact you via the HausMatch platform.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SearchResults;

import React, { useEffect, useState } from 'react';
import { getInquiries, updateInquiryStatus } from '../services/dataService';
import { Inquiry } from '../types';

const Dashboard = () => {
  const [inquiries, setInquiries] = useState<Inquiry[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  useEffect(() => {
    getInquiries().then(setInquiries);
  }, []);

  const handleStatusUpdate = async (id: string, status: 'contacted' | 'archived') => {
    await updateInquiryStatus(id, status);
    setInquiries(prev => prev.map(i => i.id === id ? { ...i, status } : i));
  };

  const selectedInquiry = inquiries.find(i => i.id === selectedId);

  // Stats
  const newLeads = inquiries.filter(i => i.status === 'new').length;

  return (
    <div className="h-[calc(100vh-4rem)] flex overflow-hidden bg-slate-100">

      {/* Sidebar List */}
      <div className="w-1/3 min-w-[320px] bg-white border-r border-slate-200 flex flex-col">
        <div className="p-5 border-b border-slate-200">
          <h2 className="text-lg font-bold text-slate-800">Lead Center</h2>
          <div className="flex gap-4 mt-2 text-sm">
             <span className="text-indigo-600 font-medium">{newLeads} New</span>
             <span className="text-slate-500">{inquiries.length} Total</span>
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {inquiries.map(inquiry => (
            <div 
              key={inquiry.id}
              onClick={() => setSelectedId(inquiry.id)}
              className={`p-4 border-b border-slate-100 cursor-pointer hover:bg-slate-50 transition-colors ${selectedId === inquiry.id ? 'bg-indigo-50 border-l-4 border-l-indigo-600' : ''}`}
            >
              <div className="flex justify-between items-start">
                <h3 className="font-medium text-slate-900">{inquiry.city}</h3>
                {inquiry.status === 'new' && <span className="bg-green-100 text-green-800 text-xs px-2 py-0.5 rounded-full">New</span>}
              </div>
              <p className="text-sm text-slate-500 mt-1">{inquiry.propertyType} • {inquiry.units} Units</p>
              <p className="text-xs text-slate-400 mt-2">{new Date(inquiry.createdAt).toLocaleDateString()}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Main Detail View */}
      <div className="flex-1 overflow-y-auto p-8">
        {selectedInquiry ? (
          <div className="max-w-3xl mx-auto space-y-6">

            {/* Header */}
            <div className="flex justify-between items-start">
               <div>
                 <h1 className="text-2xl font-bold text-slate-900">Inquiry #{selectedInquiry.id}</h1>
                 <p className="text-slate-500">Submitted by {selectedInquiry.ownerName}</p>
               </div>
               <div className="flex gap-2">
                 <button 
                  onClick={() => handleStatusUpdate(selectedInquiry.id, 'contacted')}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700"
                 >
                   Mark Contacted
                 </button>
                 <button 
                  onClick={() => handleStatusUpdate(selectedInquiry.id, 'archived')}
                  className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg text-sm font-medium hover:bg-slate-50"
                 >
                   Archive
                 </button>
               </div>
            </div>

            {/* AI Analysis Card */}
            {selectedInquiry.aiAnalysis && (
              <div className="bg-gradient-to-br from-indigo-50 to-white p-6 rounded-2xl border border-indigo-100 shadow-sm relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-10 text-indigo-900">
                  <svg className="w-24 h-24" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2a10 10 0 100 20 10 10 0 000-20zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/></svg>
                </div>
                <h3 className="text-sm font-bold text-indigo-900 uppercase tracking-wide mb-3">AI Assessment</h3>

                <div className="mb-4">
                  <div className="flex items-center gap-2 mb-2">
                    <span className="text-sm text-slate-600">Est. Management Effort:</span>
                    <span className={`px-2 py-0.5 rounded text-sm font-bold 
                      ${selectedInquiry.aiAnalysis.estimatedEffort === 'Low' ? 'bg-green-100 text-green-800' : 
                        selectedInquiry.aiAnalysis.estimatedEffort === 'High' ? 'bg-red-100 text-red-800' : 'bg-yellow-100 text-yellow-800'}`}>
                      {selectedInquiry.aiAnalysis.estimatedEffort}
                    </span>
                  </div>
                  <div className="w-full bg-slate-200 rounded-full h-1.5">
                    <div 
                      className={`h-1.5 rounded-full ${selectedInquiry.aiAnalysis.estimatedEffort === 'Low' ? 'bg-green-500 w-1/3' : selectedInquiry.aiAnalysis.estimatedEffort === 'High' ? 'bg-red-500 w-full' : 'bg-yellow-500 w-2/3'}`}
                    ></div>
                  </div>
                </div>

                <p className="text-slate-700 text-sm italic mb-4">"{selectedInquiry.aiAnalysis.summary}"</p>

                <div className="flex flex-wrap gap-2">
                   {selectedInquiry.aiAnalysis.recommendedTags.map(tag => (
                     <span key={tag} className="px-2 py-1 bg-white border border-indigo-200 text-indigo-700 text-xs rounded-md shadow-sm">
                       {tag}
                     </span>
                   ))}
                </div>
              </div>
            )}

            {/* Details Grid */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
              <h3 className="text-lg font-bold text-slate-900 mb-4">Property Details</h3>
              <dl className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-6">
                <div>
                  <dt className="text-sm font-medium text-slate-500">Property Type</dt>
                  <dd className="mt-1 text-sm text-slate-900">{selectedInquiry.propertyType}</dd>
                </div>
                <div>
                  <dt className="text-sm font-medium text-slate-500">Building Age</dt>
                  <dd className="mt-1 text-sm text-slate-900">{selectedInquiry.buildingAge}</dd>
                </div>
                <div>
                  <dt className="text-sm font-medium text-slate-500">Condition</dt>
                  <dd className="mt-1 text-sm text-slate-900">{selectedInquiry.condition}</dd>
                </div>
                <div>
                  <dt className="text-sm font-medium text-slate-500">Services Needed</dt>
                  <dd className="mt-1 text-sm text-slate-900 flex flex-wrap gap-1">
                    {selectedInquiry.servicesNeeded.map(s => <span key={s} className="bg-slate-100 px-2 py-0.5 rounded text-xs">{s}</span>)}
                  </dd>
                </div>
                <div className="sm:col-span-2">
                   <dt className="text-sm font-medium text-slate-500">Description</dt>
                   <dd className="mt-1 text-sm text-slate-900 bg-slate-50 p-3 rounded-lg">{selectedInquiry.description || "No description provided."}</dd>
                </div>
              </dl>
            </div>

            {/* Contact Actions */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 flex items-center justify-between">
               <div>
                 <h3 className="text-lg font-bold text-slate-900">Contact Owner</h3>
                 <p className="text-sm text-slate-500">{selectedInquiry.ownerEmail}</p>
               </div>
               <a href={`mailto:${selectedInquiry.ownerEmail}`} className="px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 flex items-center gap-2">
                 <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                 Send Email
               </a>
            </div>

          </div>
        ) : (
          <div className="h-full flex items-center justify-center text-slate-400">
            Select a lead to view details
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useEffect, useState } from 'react';
import { getForumThreads, createThread } from '../services/dataService';
import { ForumThread } from '../types';

const Forum = () => {
  const [threads, setThreads] = useState<ForumThread[]>([]);
  const [showCreate, setShowCreate] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newContent, setNewContent] = useState('');

  useEffect(() => {
    getForumThreads().then(setThreads);
  }, []);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle || !newContent) return;

    await createThread({
      title: newTitle,
      content: newContent,
      author: 'Current User', // Mock
      category: 'General'
    });

    setNewTitle('');
    setNewContent('');
    setShowCreate(false);
    const updated = await getForumThreads();
    setThreads(updated);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-10">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900">Manager Community</h1>
          <p className="text-slate-600">Discuss best practices, legal updates, and tech.</p>
        </div>
        <button 
          onClick={() => setShowCreate(!showCreate)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition-colors"
        >
          {showCreate ? 'Cancel' : 'New Thread'}
        </button>
      </div>

      {showCreate && (
        <form onSubmit={handleCreate} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 mb-8 animate-fade-in-down">
          <div className="mb-4">
            <label className="block text-sm font-medium text-slate-700">Topic Title</label>
            <input 
              value={newTitle}
              onChange={e => setNewTitle(e.target.value)}
              className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border"
              placeholder="e.g. New WEG accounting rules"
            />
          </div>
          <div className="mb-4">
            <label className="block text-sm font-medium text-slate-700">Content</label>
            <textarea 
              value={newContent}
              onChange={e => setNewContent(e.target.value)}
              rows={3}
              className="mt-1 block w-full rounded-md border-slate-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm p-2 border"
            />
          </div>
          <button type="submit" className="bg-slate-900 text-white px-4 py-2 rounded-md text-sm">Post Thread</button>
        </form>
      )}

      <div className="space-y-4">
        {threads.map(thread => (
          <div key={thread.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 hover:shadow-md transition-shadow cursor-pointer">
            <div className="flex justify-between items-start">
              <div>
                <span className="inline-block px-2 py-0.5 bg-slate-100 text-slate-600 text-xs rounded-full mb-2">{thread.category}</span>
                <h3 className="text-lg font-semibold text-slate-900">{thread.title}</h3>
                <p className="text-slate-500 text-sm mt-1 line-clamp-2">{thread.content}</p>
                <div className="mt-3 flex items-center text-xs text-slate-400 gap-3">
                  <span>Posted by {thread.author}</span>
                  <span>•</span>
                  <span>{new Date(thread.createdAt).toLocaleDateString()}</span>
                </div>
              </div>
              <div className="flex flex-col items-center justify-center bg-slate-50 p-3 rounded-lg min-w-[60px]">
                 <span className="font-bold text-slate-700">{thread.replies}</span>
                 <span className="text-xs text-slate-500">Replies</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Forum;

import React, { useEffect, useState, useContext } from 'react';
import { AuthContext } from '../App';
import { getMessages, sendMessage } from '../services/dataService';
import { Message } from '../types';

const Messaging = () => {
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState<Message[]>([]);
  const [replyText, setReplyText] = useState('');
  const [selectedMsg, setSelectedMsg] = useState<Message | null>(null);

  useEffect(() => {
    if (user) {
      getMessages(user.id).then(setMessages);
      // Simulate polling
      const interval = setInterval(() => {
         getMessages(user.id).then(setMessages);
      }, 5000);
      return () => clearInterval(interval);
    }
  }, [user]);

  const handleReply = async () => {
    if (!user || !selectedMsg || !replyText) return;

    await sendMessage({
      senderId: user.id,
      senderName: user.name,
      receiverId: selectedMsg.senderId, // Reply back
      subject: `Re: ${selectedMsg.subject}`,
      content: replyText,
    });

    setReplyText('');
    alert('Message sent!');
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 h-[calc(100vh-5rem)]">
      <div className="flex h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

        {/* Inbox List */}
        <div className="w-1/3 border-r border-slate-200 flex flex-col">
          <div className="p-4 border-b border-slate-200 bg-slate-50">
            <h2 className="font-bold text-slate-700">Inbox</h2>
          </div>
          <div className="flex-1 overflow-y-auto">
            {messages.length === 0 && <p className="p-4 text-slate-400 text-sm">No messages yet.</p>}
            {messages.map(msg => (
              <div 
                key={msg.id}
                onClick={() => setSelectedMsg(msg)}
                className={`p-4 border-b border-slate-100 cursor-pointer hover:bg-slate-50 ${selectedMsg?.id === msg.id ? 'bg-indigo-50' : ''}`}
              >
                <div className="flex justify-between mb-1">
                  <span className={`font-medium ${msg.senderId === user?.id ? 'text-slate-500' : 'text-slate-900'}`}>
                    {msg.senderId === user?.id ? 'To: ' : 'From: '}{msg.senderId === user?.id ? 'Recipient' : msg.senderName}
                  </span>
                  <span className="text-xs text-slate-400">{new Date(msg.timestamp).toLocaleDateString()}</span>
                </div>
                <p className="text-sm text-slate-800 font-medium truncate">{msg.subject}</p>
                <p className="text-xs text-slate-500 truncate">{msg.content}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Message View */}
        <div className="flex-1 flex flex-col">
          {selectedMsg ? (
            <>
              <div className="p-6 border-b border-slate-200">
                 <h2 className="text-xl font-bold text-slate-900 mb-2">{selectedMsg.subject}</h2>
                 <div className="flex items-center gap-2 text-sm text-slate-600">
                   <div className="w-8 h-8 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-700 font-bold">
                     {selectedMsg.senderName[0]}
                   </div>
                   <span>{selectedMsg.senderName}</span>
                   <span className="text-slate-400">&lt;ID: {selectedMsg.senderId}&gt;</span>
                 </div>
              </div>
              <div className="flex-1 p-6 overflow-y-auto bg-slate-50/50">
                <p className="whitespace-pre-wrap text-slate-800">{selectedMsg.content}</p>
              </div>
              <div className="p-4 border-t border-slate-200 bg-white">
                <div className="flex gap-2">
                  <input 
                    value={replyText} 
                    onChange={e => setReplyText(e.target.value)}
                    placeholder="Write a reply..."
                    className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                  />
                  <button onClick={handleReply} className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700">
                    Send
                  </button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex items-center justify-center text-slate-400">
              Select a message to read
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Messaging;

