// Components
import LandingPage from './components/LandingPage';
import Wizard from './components/Wizard';
import Dashboard from './components/Dashboard';
import Forum from './components/Forum';
import SearchResults from './components/SearchResults';
import Login from './components/Login';
import Messaging from './components/Messaging';

// Auth Context
interface AuthContextType {
  user: User | null;
  login: (role: UserRole) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    // Check session
    const stored = localStorage.getItem('hausmatch_user');
    if (stored) setUser(JSON.parse(stored));

    // Request notification permission
    if ('Notification' in window) {
      Notification.requestPermission();
    }
  }, []);

  const login = (role: UserRole) => {
    const mockUser: User = {
      id: role === 'manager' ? 'm1' : 's1',
      name: role === 'manager' ? 'Premium Property Mgmt' : 'Max Owner',
      email: role === 'manager' ? 'contact@premium-pm.de' : 'max@owner.de',
      role: role,
    };
    setUser(mockUser);
    localStorage.setItem('hausmatch_user', JSON.stringify(mockUser));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('hausmatch_user');
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

// Navbar
const Navbar = () => {
  const { user, logout } = useContext(AuthContext);
  const location = useLocation();

  const isActive = (path: string) => location.pathname === path ? 'text-indigo-600 font-semibold bg-indigo-50' : 'text-slate-600 hover:text-indigo-600 hover:bg-slate-50';

  return (
    <nav className="fixed top-0 w-full z-50 glass-panel border-b border-slate-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          <div className="flex items-center">
            <Link to="/" className="flex items-center gap-2">
              <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">H</div>
              <span className="text-xl font-bold text-slate-800 tracking-tight">HausMatch</span>
            </Link>
          </div>

          <div className="hidden md:flex items-center space-x-1">
            <Link to="/" className={`px-3 py-2 rounded-md text-sm transition-colors flex items-center gap-2 ${isActive('/')}`}>
              <Icons.Home /> Home
            </Link>

            {user?.role === 'seeker' && (
              <>
                 <Link to="/wizard" className={`px-3 py-2 rounded-md text-sm transition-colors flex items-center gap-2 ${isActive('/wizard')}`}>
                  <Icons.Search /> Find Manager
                </Link>
              </>
            )}

            {user?.role === 'manager' && (
              <>
                <Link to="/dashboard" className={`px-3 py-2 rounded-md text-sm transition-colors flex items-center gap-2 ${isActive('/dashboard')}`}>
                  <Icons.Dashboard /> Dashboard
                </Link>
                <Link to="/forum" className={`px-3 py-2 rounded-md text-sm transition-colors flex items-center gap-2 ${isActive('/forum')}`}>
                   <Icons.Users /> Forum
                </Link>
                 <Link to="/messages" className={`px-3 py-2 rounded-md text-sm transition-colors flex items-center gap-2 ${isActive('/messages')}`}>
                   <Icons.Mail /> Inbox
                </Link>
              </>
            )}

            {!user ? (
               <Link to="/login" className="ml-4 px-4 py-2 rounded-full bg-slate-900 text-white text-sm font-medium hover:bg-slate-800 transition-colors">
                 Log In
               </Link>
            ) : (
              <div className="flex items-center gap-4 ml-4 pl-4 border-l border-slate-200">
                <span className="text-sm font-medium text-slate-700">{user.name}</span>
                <button onClick={logout} className="text-sm text-slate-500 hover:text-red-500">Log Out</button>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

const ProtectedRoute = ({ children, allowedRoles }: React.PropsWithChildren<{ allowedRoles?: UserRole[] }>) => {
  const { user } = useContext(AuthContext);
  if (!user) return <Navigate to="/login" replace />;
  if (allowedRoles && !allowedRoles.includes(user.role)) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const App = () => {
  return (
    <AuthProvider>
      <HashRouter>
        <div className="min-h-screen pt-16">
          <Navbar />
          <Routes>
            <Route path="/" element={<LandingPage />} />
            <Route path="/login" element={<Login />} />
            <Route path="/wizard" element={<Wizard />} />
            <Route path="/search-results" element={<SearchResults />} />

            <Route path="/dashboard" element={
              <ProtectedRoute allowedRoles={['manager']}>
                <Dashboard />
              </ProtectedRoute>
            } />
            <Route path="/forum" element={
              <ProtectedRoute allowedRoles={['manager']}>
                <Forum />
              </ProtectedRoute>
            } />
            <Route path="/messages" element={
               <ProtectedRoute allowedRoles={['manager']}>
                <Messaging />
              </ProtectedRoute>
            } />

            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </div>
      </HashRouter>
    </AuthProvider>
  );
};

export default App;
