            <Route path="/search-results" element={<SearchResults />} />

            <Route path="/dashboard" element={
              <ProtectedRoute allowedRoles={['manager']}>
                <Dashboard />
              </ProtectedRoute>
            } />
            <Route path="/forum" element={
              <ProtectedRoute allowedRoles={['manager']}>
                <Forum />
              </ProtectedRoute>
            } />
            <Route path="/messages" element={
               <ProtectedRoute allowedRoles={['manager']}>
                <Messaging />
              </ProtectedRoute>
            } />

            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </div>
      </HashRouter>
    </AuthProvider>
  );
};

export default App;
export { AuthContext };

import React, { useState, useContext, useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { AuthContext } from '../App';
import { analyzePropertyRequirement, getAIAdvisorResponse } from '../services/geminiService';
import { createInquiry } from '../services/dataService';
import { Inquiry } from '../types';

const STEPS = ['Location', 'Services', 'Technical', 'Review'];

const Wizard = () => {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    city: searchParams.get('city') || '',
    units: 1,
    propertyType: 'WEG',
    servicesNeeded: [] as string[],
    buildingAge: '',
    condition: 'Good',
    description: '',
  });

  // Chat Advisor State
  const [chatOpen, setChatOpen] = useState(false);
  const [chatHistory, setChatHistory] = useState<{role: string, parts: {text: string}[]}[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const handleNext = () => setStep(p => p + 1);
  const handleBack = () => setStep(p => p - 1);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const analysis = await analyzePropertyRequirement(formData);
      await createInquiry({
        ...formData,
        ownerId: user?.id || 'guest',
        ownerName: user?.name || 'Guest User',
        ownerEmail: user?.email || 'guest@example.com',
        status: 'new',
        aiAnalysis: analysis,
        units: Number(formData.units),
        propertyType: formData.propertyType as any,
      });
      navigate(`/search-results?city=${encodeURIComponent(formData.city)}`);
    } catch (e) {
      console.error(e);
      alert('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleChat = async () => {
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatLoading(true);

    const newHistory = [...chatHistory, { role: 'user', parts: [{ text: userMsg }] }];
    setChatHistory(newHistory);

    const aiResponse = await getAIAdvisorResponse(newHistory, userMsg);

    setChatHistory(prev => [...prev, { role: 'model', parts: [{ text: aiResponse }] }]);
    setChatLoading(false);
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-12 flex gap-8 items-start relative">
      {/* Main Wizard */}
      <div className="flex-1 w-full max-w-3xl mx-auto">
        <div className="mb-10 text-center">
            <h1 className="text-3xl font-bold text-slate-900 mb-2">Find your Property Manager</h1>
            <p className="text-slate-500">Step {step + 1} of {STEPS.length}</p>

            <div className="mt-4 flex justify-center gap-2">
              {STEPS.map((_, i) => (
                <div key={i} className={`h-1.5 rounded-full transition-all duration-300 ${i <= step ? 'w-8 bg-indigo-600' : 'w-2 bg-slate-200'}`} />
              ))}
            </div>
        </div>

        <div className="glass-card rounded-3xl p-8 sm:p-12 min-h-[500px] flex flex-col justify-between shadow-2xl shadow-indigo-100/50 relative overflow-hidden">

          <div className="absolute top-0 right-0 p-8 opacity-5">
             <svg className="w-64 h-64 text-indigo-900" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L1 21h22L12 2zm0 3.516L20.297 19H3.703L12 5.516zM11 16h2v2h-2v-2zm0-5h2v4h-2v-4z"/></svg>
          </div>

          <div className="relative z-10 animate-fade-in-up">
            {step === 0 && (
              <div className="space-y-8">
                <h2 className="text-2xl font-bold text-slate-800">Where is the property located?</h2>
                <div>
                  <label className="block text-sm font-semibold text-slate-600 mb-2">City</label>
                  <input
                    type="text"
                    value={formData.city}
                    onChange={e => setFormData({...formData, city: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-sm ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all placeholder:text-slate-400"
                    placeholder="e.g. Munich"
                    autoFocus
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-600 mb-2">Number of Units</label>
                  <input
                    type="number"
                    value={formData.units}
                    onChange={e => setFormData({...formData, units: Number(e.target.value)})}
                    className="w-full bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-sm ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
                </div>
              </div>
            )}

            {step === 1 && (
               <div className="space-y-8">
                 <h2 className="text-2xl font-bold text-slate-800">Services & Type</h2>
                 <div>
                    <label className="block text-sm font-semibold text-slate-600 mb-2">Property Type</label>
                    <select 
                      value={formData.propertyType}
                      onChange={e => setFormData({...formData, propertyType: e.target.value})}
                      className="w-full bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-sm ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all"
                    >
                      <option value="WEG">WEG (Homeowners Association)</option>
                      <option value="Rental">Rental House (Mietshaus)</option>
                      <option value="Commercial">Commercial</option>
                    </select>
                 </div>
                 <div>
                   <label className="block text-sm font-semibold text-slate-600 mb-3">Specific Needs</label>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                     {['Accounting', 'Maintenance', 'Cleaning', 'Legal Representation', 'Tenant Search'].map(s => (
                       <label key={s} className={`flex items-center space-x-3 p-4 rounded-xl cursor-pointer border transition-all ${formData.servicesNeeded.includes(s) ? 'bg-indigo-50 border-indigo-200 shadow-sm' : 'bg-white border-slate-200 hover:bg-slate-50'}`}>
                         <input 
                            type="checkbox" 
                            checked={formData.servicesNeeded.includes(s)}
                            onChange={e => {
                              const current = formData.servicesNeeded;
                              setFormData({
                                ...formData,
                                servicesNeeded: current.includes(s) ? current.filter(x => x !== s) : [...current, s]
                              })
