                         />
                         <span className="text-slate-700 font-medium">{s}</span>
                       </label>
                     ))}
                   </div>
                 </div>
               </div>
            )}

            {step === 2 && (
               <div className="space-y-8">
                <h2 className="text-2xl font-bold text-slate-800">Technical Details</h2>
                <div className="grid grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-semibold text-slate-600 mb-2">Building Age</label>
                        <input
                        type="text"
                        value={formData.buildingAge}
                        onChange={e => setFormData({...formData, buildingAge: e.target.value})}
                        className="w-full bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-sm ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all"
                        placeholder="Year"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-semibold text-slate-600 mb-2">Condition</label>
                        <select
                        value={formData.condition}
                        onChange={e => setFormData({...formData, condition: e.target.value})}
                        className="w-full bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-sm ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all"
                        >
                        <option>New / Excellent</option>
                        <option>Good</option>
                        <option>Needs Renovation</option>
                        <option>Critical</option>
                        </select>
                    </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-600 mb-2">Additional Notes</label>
                  <textarea
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                    rows={4}
                    className="w-full bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-sm ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all resize-none"
                    placeholder="Describe specific issues or requirements..."
                  />
                </div>
               </div>
            )}

            {step === 3 && (
              <div className="space-y-8 text-center py-8">
                 <div className="mx-auto w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600 mb-6 animate-pulse">
