                 </div>
                 <h2 className="text-3xl font-bold text-slate-900">Ready to Match?</h2>
                 <p className="text-slate-600 text-lg max-w-md mx-auto">
                   Our AI is ready to analyze your request and scan for the best property managers in <span className="font-semibold text-indigo-600">{formData.city}</span>.
                 </p>
                 <div className="inline-flex flex-wrap justify-center gap-2 mt-4">
                     {formData.servicesNeeded.map(s => (
                         <span key={s} className="px-3 py-1 bg-white border border-slate-200 rounded-full text-xs font-medium text-slate-500">{s}</span>
                     ))}
                 </div>
              </div>
            )}
          </div>

          {/* Controls */}
          <div className="mt-12 flex justify-between relative z-10 pt-6 border-t border-slate-100">
            {step > 0 ? (
              <button onClick={handleBack} className="px-8 py-3 rounded-xl text-slate-600 font-medium hover:bg-slate-50 transition-colors">
                Back
              </button>
            ) : <div />}

            {step < STEPS.length - 1 ? (
              <button onClick={handleNext} className="px-10 py-3 bg-slate-900 text-white rounded-xl font-semibold shadow-lg shadow-slate-900/20 hover:bg-slate-800 hover:scale-105 transition-all">
                Continue
