import React, { useEffect, useState, useContext } from 'react';
import { AuthContext } from '../App';
import { getMessages, sendMessage } from '../services/dataService';
import { Message } from '../types';

const Messaging = () => {
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState<Message[]>([]);
  const [replyText, setReplyText] = useState('');
  const [selectedMsg, setSelectedMsg] = useState<Message | null>(null);

  useEffect(() => {
    if (user) {
      getMessages(user.id).then(setMessages);
      const interval = setInterval(() => {
         getMessages(user.id).then(setMessages);
      }, 5000);
      return () => clearInterval(interval);
    }
  }, [user]);

  const handleReply = async () => {
    if (!user || !selectedMsg || !replyText) return;

    await sendMessage({
      senderId: user.id,
      senderName: user.name,
      receiverId: selectedMsg.senderId,
      subject: `Re: ${selectedMsg.subject}`,
      content: replyText,
    });

    setReplyText('');
    alert('Message sent!');
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 h-[calc(100vh-6rem)]">
      <div className="flex h-full glass-card rounded-2xl overflow-hidden shadow-2xl shadow-slate-200">

        {/* Inbox List */}
        <div className="w-1/3 min-w-[300px] border-r border-slate-100 flex flex-col bg-white/50 backdrop-blur-sm">
          <div className="p-6 border-b border-slate-100">
            <h2 className="font-bold text-xl text-slate-800">Messages</h2>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {messages.length === 0 && <p className="p-6 text-slate-400 text-sm text-center">No messages yet.</p>}
            {messages.map(msg => (
              <div 
                key={msg.id}
                onClick={() => setSelectedMsg(msg)}
                className={`p-4 rounded-xl cursor-pointer transition-all ${
                    selectedMsg?.id === msg.id 
                    ? 'bg-white shadow-md border border-slate-50' 
                    : 'hover:bg-white/60'
                }`}
              >
                <div className="flex justify-between mb-1">
                  <span className={`font-semibold text-sm ${msg.senderId === user?.id ? 'text-slate-500' : 'text-slate-900'}`}>
                    {msg.senderId === user?.id ? 'To: ' : ''}{msg.senderId === user?.id ? 'Recipient' : msg.senderName}
                  </span>
                  <span className="text-[10px] text-slate-400 bg-slate-50 px-2 py-0.5 rounded-full">{new Date(msg.timestamp).toLocaleDateString()}</span>
                </div>
                <p className={`text-sm font-medium truncate mb-0.5 ${selectedMsg?.id === msg.id ? 'text-indigo-600' : 'text-slate-700'}`}>{msg.subject}</p>
                <p className="text-xs text-slate-500 truncate opacity-80">{msg.content}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Message View */}
        <div className="flex-1 flex flex-col bg-white/80">
          {selectedMsg ? (
            <>
              <div className="p-8 border-b border-slate-100">
                 <div className="flex items-center gap-3 mb-4">
                     <div className="w-10 h-10 rounded-full bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white font-bold shadow-lg shadow-indigo-200">
                         {selectedMsg.senderName[0]}
                     </div>
                     <div>
                        <h2 className="text-xl font-bold text-slate-900">{selectedMsg.subject}</h2>
                        <div className="flex items-center gap-2 text-sm text-slate-500">
                            <span>From: <span className="font-medium text-slate-700">{selectedMsg.senderName}</span></span>
                        </div>
                     </div>
                 </div>
              </div>
              <div className="flex-1 p-8 overflow-y-auto">
                <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 text-slate-700 leading-relaxed whitespace-pre-wrap">
                    {selectedMsg.content}
                </div>
              </div>
              <div className="p-6 border-t border-slate-100 bg-white">
                <div className="flex gap-3 relative">
                  <input 
                    value={replyText} 
                    onChange={e => setReplyText(e.target.value)}
                    placeholder="Write a reply..."
                    className="flex-1 bg-slate-50 border-0 rounded-xl px-5 py-4 text-slate-900 shadow-inner ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
                  <button onClick={handleReply} className="absolute right-2 top-2 bottom-2 px-6 bg-slate-900 text-white rounded-lg text-sm font-medium hover:bg-slate-800 transition-colors shadow-lg shadow-slate-900/10">
                    Send
                  </button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-slate-300">
               <svg className="w-24 h-24 mb-4 opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
               <p className="font-medium">Select a message to start reading</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
