export default Messaging;

import { Inquiry, ForumThread, Message } from "../types";
import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  getDocs, 
  updateDoc, 
  doc, 
  query, 
  orderBy, 
  where 
} from "firebase/firestore";

// --- CONFIGURATION ---
// TODO: Replace with your actual Firebase Project keys from console.firebase.google.com
const firebaseConfig = {
  apiKey: "YOUR_API_KEY_HERE",
  authDomain: "your-project.firebaseapp.com",
  projectId: "your-project-id",
  storageBucket: "your-project.appspot.com",
  messagingSenderId: "123456789",
  appId: "1:123456789:web:abcdef"
};

// Check if Firebase is configured
const isFirebaseConfigured = firebaseConfig.apiKey !== "YOUR_API_KEY_HERE";

let db: any;
if (isFirebaseConfigured) {
  try {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    console.log("🔥 Firebase initialized successfully");
  } catch (e) {
    console.error("Firebase init failed:", e);
  }
} else {
  console.warn("⚠️ Firebase not configured. Using LocalStorage mock backend.");
}

// Helper to simulate network delay for mock mode
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const STORAGE_KEYS = {
  INQUIRIES: 'hausmatch_inquiries',
  THREADS: 'hausmatch_threads',
  MESSAGES: 'hausmatch_messages',
};

// --- INQUIRIES ---

export const getInquiries = async (): Promise<Inquiry[]> => {
  if (isFirebaseConfigured && db) {
    try {
      const q = query(collection(db, "inquiries"), orderBy("createdAt", "desc"));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Inquiry));
    } catch (e) {
      console.error("Fetch inquiries failed", e);
      return [];
    }
  }

  // Fallback
  await delay(500);
  const data = localStorage.getItem(STORAGE_KEYS.INQUIRIES);
  return data ? JSON.parse(data) : [];
};

export const createInquiry = async (inquiry: Omit<Inquiry, 'id' | 'createdAt'>): Promise<Inquiry> => {
  const timestamp = Date.now();

  if (isFirebaseConfigured && db) {
    const docRef = await addDoc(collection(db, "inquiries"), {
      ...inquiry,
      createdAt: timestamp
    });
    return { ...inquiry, id: docRef.id, createdAt: timestamp };
  }

  // Fallback
  await delay(800);
  const inquiries = await getInquiries();
  const newInquiry: Inquiry = {
    ...inquiry,
    id: Math.random().toString(36).substr(2, 9),
    createdAt: timestamp,
  };
  inquiries.unshift(newInquiry);
  localStorage.setItem(STORAGE_KEYS.INQUIRIES, JSON.stringify(inquiries));
  return newInquiry;
};

export const updateInquiryStatus = async (id: string, status: 'contacted' | 'archived') => {
  if (isFirebaseConfigured && db) {
    const docRef = doc(db, "inquiries", id);
    await updateDoc(docRef, { status });
    return;
  }

  // Fallback
  const inquiries = await getInquiries();
  const updated = inquiries.map(i => i.id === id ? { ...i, status } : i);
  localStorage.setItem(STORAGE_KEYS.INQUIRIES, JSON.stringify(updated));
};

// --- FORUM ---

const MOCK_THREADS: ForumThread[] = [
  { id: '1', title: 'WEG Reform 2024 updates?', author: 'ManagerHans', category: 'Legal', content: 'Has anyone started implementing the new digital meeting protocols?', replies: 12, views: 340, createdAt: Date.now() - 86400000 },
  { id: '2', title: 'Best software for accounting?', author: 'PropTechLisa', category: 'Tech', content: 'Looking for alternatives to the legacy systems.', replies: 5, views: 120, createdAt: Date.now() - 172800000 },
];

export const getForumThreads = async (): Promise<ForumThread[]> => {
  if (isFirebaseConfigured && db) {
    try {
      const q = query(collection(db, "forumThreads"), orderBy("createdAt", "desc"));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as ForumThread));
    } catch (e) {
      console.error("Fetch threads failed", e);
      return [];
    }
  }

  // Fallback
  await delay(300);
  const data = localStorage.getItem(STORAGE_KEYS.THREADS);
  if (!data) {
    localStorage.setItem(STORAGE_KEYS.THREADS, JSON.stringify(MOCK_THREADS));
    return MOCK_THREADS;
  }
  return JSON.parse(data);
};

export const createThread = async (thread: Omit<ForumThread, 'id' | 'replies' | 'views' | 'createdAt'>) => {
  const timestamp = Date.now();

  if (isFirebaseConfigured && db) {
    await addDoc(collection(db, "forumThreads"), {
      ...thread,
      replies: 0,
      views: 0,
      createdAt: timestamp
    });
    return;
  }

  // Fallback
  await delay(400);
  const threads = await getForumThreads();
  const newThread: ForumThread = {
    ...thread,
    id: Math.random().toString(36).substr(2, 9),
    replies: 0,
    views: 0,
    createdAt: timestamp,
  };
  threads.unshift(newThread);
  localStorage.setItem(STORAGE_KEYS.THREADS, JSON.stringify(threads));
};

// --- MESSAGING ---

export const getMessages = async (userId: string): Promise<Message[]> => {
  if (isFirebaseConfigured && db) {
    try {
      // Note: Firestore OR queries are complex. For simple use, we fetch both and merge in memory or perform two queries.
      // For this demo, we'll fetch all messages and filter in memory (inefficient for prod, fine for demo)
      // Or use a composite index if configured.
      // Let's do a simple approach: Fetch messages where this user is sender OR receiver

      const q1 = query(collection(db, "messages"), where("receiverId", "==", userId));
      const q2 = query(collection(db, "messages"), where("senderId", "==", userId));

      const [snap1, snap2] = await Promise.all([getDocs(q1), getDocs(q2)]);

      const messagesMap = new Map();

      snap1.docs.forEach(d => messagesMap.set(d.id, { id: d.id, ...d.data() }));
      snap2.docs.forEach(d => messagesMap.set(d.id, { id: d.id, ...d.data() }));

      const messages = Array.from(messagesMap.values()) as Message[];
      return messages.sort((a, b) => b.timestamp - a.timestamp);

    } catch (e) {
      console.error("Fetch messages failed", e);
      return [];
    }
  }

  // Fallback
  await delay(300);
  const data = localStorage.getItem(STORAGE_KEYS.MESSAGES);
  const messages: Message[] = data ? JSON.parse(data) : [];
  return messages.filter(m => m.receiverId === userId || m.senderId === userId).sort((a,b) => b.timestamp - a.timestamp);
};

export const sendMessage = async (msg: Omit<Message, 'id' | 'timestamp' | 'isRead'>) => {
  const timestamp = Date.now();

  if (isFirebaseConfigured && db) {
    await addDoc(collection(db, "messages"), {
      ...msg,
      isRead: false,
      timestamp: timestamp
    });
    return;
  }

  // Fallback
  await delay(400);
  const data = localStorage.getItem(STORAGE_KEYS.MESSAGES);
  const messages: Message[] = data ? JSON.parse(data) : [];
  const newMessage: Message = {
    ...msg,
    id: Math.random().toString(36).substr(2, 9),
    isRead: false,
    timestamp: timestamp,
  };
  messages.push(newMessage);
  localStorage.setItem(STORAGE_KEYS.MESSAGES, JSON.stringify(messages));

  if ('Notification' in window && Notification.permission === 'granted') {
    new Notification(`New Message from ${msg.senderName}`, { body: msg.subject });
  }
};

