  if (isFirebaseConfigured && db) {
    try {
      // Note: Firestore OR queries are complex. For simple use, we fetch both and merge in memory or perform two queries.
      // For this demo, we'll fetch all messages and filter in memory (inefficient for prod, fine for demo)
      // Or use a composite index if configured.
      // Let's do a simple approach: Fetch messages where this user is sender OR receiver

      const q1 = query(collection(db, "messages"), where("receiverId", "==", userId));
      const q2 = query(collection(db, "messages"), where("senderId", "==", userId));

      const [snap1, snap2] = await Promise.all([getDocs(q1), getDocs(q2)]);

      const messagesMap = new Map();

      snap1.docs.forEach(d => messagesMap.set(d.id, { id: d.id, ...d.data() }));
      snap2.docs.forEach(d => messagesMap.set(d.id, { id: d.id, ...d.data() }));

      const messages = Array.from(messagesMap.values()) as Message[];
      return messages.sort((a, b) => b.timestamp - a.timestamp);

    } catch (e) {
      console.error("Fetch messages failed", e);
      return [];
    }
  }

  // Fallback
  await delay(300);
  const data = localStorage.getItem(STORAGE_KEYS.MESSAGES);
  const messages: Message[] = data ? JSON.parse(data) : [];
  return messages.filter(m => m.receiverId === userId || m.senderId === userId).sort((a,b) => b.timestamp - a.timestamp);
};

