    const [snap1, snap2] = await Promise.all([getDocs(q1), getDocs(q2)]);

    const messagesMap = new Map();
    snap1.docs.forEach(d => messagesMap.set(d.id, { id: d.id, ...d.data() }));
    snap2.docs.forEach(d => messagesMap.set(d.id, { id: d.id, ...d.data() }));

    const messages = Array.from(messagesMap.values()) as Message[];
    return messages.sort((a, b) => b.timestamp - a.timestamp);

