};

const ProtectedRoute = ({ children, allowedRoles }: React.PropsWithChildren<{ allowedRoles?: UserRole[] }>) => {
  const { user, loading } = useContext(AuthContext);
  if (loading) return <div className="h-screen flex items-center justify-center text-slate-400">Loading...</div>;
  if (!user) return <Navigate to="/login" replace />;
  if (allowedRoles && !allowedRoles.includes(user.role)) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const App = () => {
  return (
    <AuthProvider>
      <HashRouter>
        <div className="min-h-screen pt-16 selection:bg-indigo-100 selection:text-indigo-900">
          <Navbar />
          <Routes>
            <Route path="/" element={<LandingPage />} />
            <Route path="/login" element={<Login />} />
            <Route path="/wizard" element={<Wizard />} />
            <Route path="/search-results" element={<SearchResults />} />
            <Route path="/dashboard" element={
              <ProtectedRoute allowedRoles={['manager']}>
                <Dashboard />
              </ProtectedRoute>
            } />
            <Route path="/forum" element={
              <ProtectedRoute allowedRoles={['manager']}>
                <Forum />
              </ProtectedRoute>
            } />
            <Route path="/messages" element={
               <ProtectedRoute allowedRoles={['manager']}>
                <Messaging />
              </ProtectedRoute>
            } />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </div>
      </HashRouter>
    </AuthProvider>
  );
};

export default App;
export { AuthContext };

import React, { useEffect, useState, useContext, useRef } from 'react';
import { AuthContext } from '../App';
import { getMessages, sendMessage, markMessageRead } from '../services/dataService';
import { Message } from '../types';

const Messaging = () => {
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState<Message[]>([]);
  const [replyText, setReplyText] = useState('');
  const [selectedMsg, setSelectedMsg] = useState<Message | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (user) {
      const fetchMessages = () => {
        getMessages(user.id).then(setMessages);
      };

      fetchMessages();
      const interval = setInterval(fetchMessages, 5000);
      return () => clearInterval(interval);
    }
  }, [user]);

  // Handle marking message as read
  useEffect(() => {
    if (selectedMsg && !selectedMsg.read && selectedMsg.receiverId === user?.id) {
      markMessageRead(selectedMsg.id).then(() => {
        setMessages(prev => prev.map(m => m.id === selectedMsg.id ? { ...m, read: true } : m));
      });
    }
    scrollRef.current?.scrollTo(0, 0);
  }, [selectedMsg, user?.id]);

  const handleReply = async () => {
    if (!user || !selectedMsg || !replyText) return;

    await sendMessage({
      senderId: user.id,
      senderName: user.name,
      receiverId: selectedMsg.senderId,
      subject: selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`,
      content: replyText,
    });

    setReplyText('');
    // Optimistic feedback could be added here, for now a simple alert
    const notification = document.createElement('div');
    notification.className = 'fixed bottom-4 right-4 bg-green-600 text-white px-6 py-3 rounded-xl shadow-2xl z-[100] animate-fade-in-up';
    notification.innerText = 'Message sent successfully!';
    document.body.appendChild(notification);
    setTimeout(() => notification.remove(), 3000);
  };

  const formatTimestamp = (ts: any) => {
    const date = new Date(ts);
    const now = new Date();
