import React, { useEffect, useState, useContext, useRef } from 'react';
import { AuthContext } from '../App';
import { getMessages, sendMessage, markMessageRead } from '../services/dataService';
import { Message } from '../types';

const Messaging = () => {
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState<Message[]>([]);
  const [replyText, setReplyText] = useState('');
  const [selectedMsg, setSelectedMsg] = useState<Message | null>(null);
  const [view, setView] = useState<'inbox' | 'sent'>('inbox');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (user) {
      const fetchMessages = () => {
        getMessages(user.id).then(setMessages);
      };

      fetchMessages();
      const interval = setInterval(fetchMessages, 5000);
      return () => clearInterval(interval);
    }
  }, [user]);

  // Mark message as read when selected
  useEffect(() => {
    if (selectedMsg && !selectedMsg.read && selectedMsg.receiverId === user?.id) {
      markMessageRead(selectedMsg.id).then(() => {
        setMessages(prev => prev.map(m => m.id === selectedMsg.id ? { ...m, read: true } : m));
      });
    }
    scrollRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  }, [selectedMsg, user?.id]);

  const filteredMessages = messages.filter(m => 
    view === 'inbox' ? m.receiverId === user?.id : m.senderId === user?.id
  );

  const handleReply = async () => {
    if (!user || !selectedMsg || !replyText.trim()) return;

    await sendMessage({
      senderId: user.id,
      senderName: user.name,
      receiverId: selectedMsg.senderId === user.id ? selectedMsg.receiverId : selectedMsg.senderId,
      subject: selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`,
      content: replyText,
    });

    setReplyText('');
    const notification = document.createElement('div');
    notification.className = 'fixed bottom-4 right-4 bg-slate-900 text-white px-6 py-3 rounded-2xl shadow-2xl z-[100] animate-fade-in-up border border-white/10';
    notification.innerText = 'Message sent!';
    document.body.appendChild(notification);
    setTimeout(() => notification.remove(), 2500);
  };

  const formatTime = (ts: any) => {
    return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getFullTimestamp = (ts: any) => {
    return new Date(ts).toLocaleString([], { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric', 
      year: 'numeric',
      hour: '2-digit', 
      minute: '2-digit'
