    <div className="flex -space-x-1.5 items-center">
      <svg className={`w-3.5 h-3.5 ${read ? 'text-indigo-500' : color}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 13l4 4L19 7" /></svg>
      <svg className={`w-3.5 h-3.5 ${read ? 'text-indigo-500' : 'hidden'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 13l4 4L19 7" /></svg>
    </div>
