  return (
    <div className="max-w-7xl mx-auto px-4 py-8 h-[calc(100vh-6rem)]">
      <div className="flex h-full glass-card rounded-[2.5rem] overflow-hidden shadow-2xl shadow-indigo-100/50 border border-white/60">

        {/* Navigation & List */}
        <div className="w-1/3 min-w-[340px] border-r border-slate-100 flex flex-col bg-white/40 backdrop-blur-md">
          <div className="p-6 border-b border-slate-100/50">
            <h2 className="font-extrabold text-2xl text-slate-900 tracking-tight mb-6">Messages</h2>
            <div className="flex p-1 bg-slate-100/50 rounded-2xl gap-1">
              <button 
                onClick={() => setView('inbox')}
                className={`flex-1 py-2 rounded-xl text-sm font-bold transition-all ${view === 'inbox' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Inbox {messages.filter(m => !m.read && m.receiverId === user?.id).length > 0 && `(${messages.filter(m => !m.read && m.receiverId === user?.id).length})`}
              </button>
              <button 
                onClick={() => setView('sent')}
                className={`flex-1 py-2 rounded-xl text-sm font-bold transition-all ${view === 'sent' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Sent
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {filteredMessages.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-48 text-slate-400 opacity-50">
                <svg className="w-12 h-12 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" /></svg>
                <p className="text-sm font-medium">No messages in {view}</p>
              </div>
            ) : filteredMessages.map(msg => {
              const isUnread = !msg.read && msg.receiverId === user?.id;
              const isMe = msg.senderId === user?.id;

              return (
                <div 
                  key={msg.id}
