                    </span>
                  </div>
                  <p className={`text-sm mb-1 truncate ${isUnread ? 'font-bold text-slate-900' : 'text-slate-700'}`}>
                    {msg.subject}
                  </p>
                  <div className="flex items-center justify-between">
                    <p className="text-xs text-slate-400 truncate line-clamp-1 flex-1 pr-4">
                      {isMe && <span className="text-indigo-400 font-bold mr-1">You:</span>}
                      {msg.content}
                    </p>
                    {isMe && <ReadReceipt read={msg.read} color="text-slate-200" />}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Message Content View */}
        <div className="flex-1 flex flex-col bg-white/60">
          {selectedMsg ? (
            <>
              <div className="p-8 border-b border-slate-100 bg-white/40 backdrop-blur-md">
                 <div className="flex items-center justify-between">
                    <div className="flex items-center gap-5">
                        <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-slate-900 to-indigo-900 flex items-center justify-center text-white font-black text-xl shadow-2xl shadow-slate-200 ring-4 ring-white">
                            {selectedMsg.senderName[0]}
                        </div>
                        <div>
                           <h2 className="text-2xl font-black text-slate-900 tracking-tight leading-none mb-2">{selectedMsg.subject}</h2>
                           <div className="flex items-center gap-3 text-xs text-slate-500 font-medium">
                               <span>From: <span className="text-slate-900 font-bold">{selectedMsg.senderName}</span></span>
                               <span className="w-1.5 h-1.5 rounded-full bg-slate-200"></span>
                               <span>{getFullTimestamp(selectedMsg.timestamp)}</span>
                           </div>
                        </div>
                    </div>
                 </div>
              </div>

              <div ref={scrollRef} className="flex-1 p-8 overflow-y-auto space-y-6 bg-slate-50/20">
                <div className="flex flex-col gap-2 max-w-4xl mx-auto">
                    <div className={`flex ${selectedMsg.senderId === user?.id ? 'justify-end' : 'justify-start'}`}>
                        <div className={`relative max-w-[85%] rounded-[2rem] p-8 shadow-2xl shadow-indigo-100/20 text-base leading-relaxed whitespace-pre-wrap ${
                            selectedMsg.senderId === user?.id 
                            ? 'bg-slate-900 text-white rounded-tr-none' 
                            : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'
                        }`}>
                            {selectedMsg.content}
                            <div className={`absolute bottom-4 right-6 flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest ${
                                selectedMsg.senderId === user?.id ? 'text-white/40' : 'text-slate-300'
                            }`}>
                                {formatTime(selectedMsg.timestamp)}
                                {selectedMsg.senderId === user?.id && <ReadReceipt read={selectedMsg.read} color="text-white/20" />}
                            </div>
                        </div>
                    </div>
                </div>
              </div>

              <div className="p-6 border-t border-slate-100 bg-white/80 backdrop-blur-md">
                <div className="max-w-4xl mx-auto flex gap-4 items-end">
                  <div className="flex-1 relative">
                    <textarea 
                        rows={1}
                        value={replyText} 
                        onChange={e => setReplyText(e.target.value)}
                        onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleReply(); } }}
                        placeholder="Type your response..."
                        className="w-full bg-slate-100/50 border-0 rounded-[1.5rem] px-6 py-4 text-slate-900 shadow-inner focus:bg-white focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all outline-none resize-none max-h-32 text-sm font-medium"
                    />
                  </div>
                  <button 
                    onClick={handleReply} 
                    disabled={!replyText.trim()}
                    className="p-4 bg-slate-900 text-white rounded-full hover:bg-slate-800 transition-all shadow-xl shadow-slate-900/10 hover:-translate-y-1 disabled:opacity-20 disabled:hover:translate-y-0 disabled:scale-100 active:scale-95"
                  >
                    <svg className="w-6 h-6 rotate-45" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                  </button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-slate-400/50">
               <div className="relative mb-6">
                  <div className="absolute -inset-10 bg-indigo-50 rounded-full blur-3xl opacity-40 animate-pulse"></div>
