             <div className="flex-1 p-6 overflow-y-auto space-y-4 bg-slate-50/50 scroll-smooth custom-scrollbar">
               {chatHistory.length === 0 && (
                 <div className="text-center mt-12 space-y-3 p-4">
                     <p className="text-sm font-bold text-slate-900">Wie kann ich helfen?</p>
                     <p className="text-xs text-slate-500 leading-relaxed">Ich erkläre Ihnen WEG-Gesetze, Mietverträge oder die Pflichten einer Hausverwaltung.</p>
                 </div>
               )}
               {chatHistory.map((msg, idx) => (
                 <div key={idx} className={`p-4 rounded-2xl text-sm max-w-[85%] shadow-sm leading-relaxed ${msg.role === 'user' ? 'bg-indigo-600 text-white ml-auto rounded-br-none' : 'bg-white text-slate-700 mr-auto rounded-bl-none border border-slate-100'}`}>
                   {msg.parts[0].text}
                 </div>
               ))}
               {chatLoading && <div className="p-4 bg-white rounded-2xl w-16 animate-pulse">...</div>}
               <div ref={chatEndRef} />
             </div>
             <div className="p-4 bg-white border-t border-slate-100">
               <div className="flex gap-2 items-center bg-slate-50 border border-slate-200 rounded-full px-2 py-1">
                <input 
                    value={chatInput}
                    onChange={e => setChatInput(e.target.value)}
                    onKeyDown={e => e.key === 'Enter' && handleChat()}
                    placeholder="Frage stellen..."
                    className="flex-1 text-sm bg-transparent border-0 focus:ring-0 px-3 py-2"
                />
                <button 
                    onClick={handleChat} 
                    className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 transition-colors"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
                </button>
               </div>
             </div>
          </div>
        )}
        <button 
          onClick={() => setChatOpen(!chatOpen)}
          className={`p-4 rounded-full shadow-2xl flex items-center gap-3 transition-all duration-300 hover:scale-105 ${chatOpen ? 'bg-slate-900 text-white' : 'bg-indigo-600 text-white'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          <span className="font-black text-xs uppercase tracking-widest pr-2">Rechts-Check</span>
        </button>
      </div>
    </div>
  );
};

