const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// 1. Objektanalyse auf Deutsch
export const analyzePropertyRequirement = async (
  formData: any
): Promise<InquiryAnalysis> => {
  const prompt = `
    Analysiere diese Immobilien-Anfrage für eine Hausverwaltung in Deutschland.

    Daten:
    Stadt: ${formData.city}
    Einheiten: ${formData.units}
    Typ: ${formData.propertyType}
    Leistungen: ${formData.servicesNeeded.join(", ")}
    Baujahr: ${formData.buildingAge}
    Zustand: ${formData.condition}
    Beschreibung: ${formData.description}

    Erstelle eine Zusammenfassung, eine Liste der Kernanforderungen und schätze den Verwaltungsaufwand ein (Niedrig/Mittel/Hoch).
    Schlage zudem passende Kategorisierungs-Tags vor. Antworte ausschließlich auf Deutsch.
  `;

  try {
    const response = await ai.models.generateContent({
      // Upgraded to pro model for better analytical reasoning
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            keyRequirements: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
            },
            estimatedEffort: {
              type: Type.STRING,
              // Fixed: Using German values directly to match types.ts and UI requirements
              enum: ["Niedrig", "Mittel", "Hoch"],
            },
            recommendedTags: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
            },
          },
          required: ["summary", "keyRequirements", "estimatedEffort", "recommendedTags"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("Keine Antwort von der KI");
    const data = JSON.parse(text);
    // Data now maps directly to InquiryAnalysis without manual transformation
    return data as InquiryAnalysis;
  } catch (error) {
    console.error("KI-Analysefehler:", error);
    // Fixed: Ensure the fallback values match the updated InquiryAnalysis type
    return {
      summary: "Objektanalyse momentan nicht möglich.",
      keyRequirements: ["Manuelle Prüfung erforderlich"],
      estimatedEffort: "Mittel",
      recommendedTags: ["In Prüfung"],
    };
  }
};

// 2. Verwalter-Suche mit Grounding
export const searchPropertyManagers = async (city: string): Promise<ManagerSearchResult> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Finde die 3-5 besten Hausverwaltungen in ${city}, Deutschland. Erstelle eine kurze Zusammenfassung für jede Firma, warum sie empfehlenswert ist. Nutze die Google Suche für aktuelle Daten.`,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "Keine Ergebnisse gefunden.";
    const sources: { title: string; url: string }[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web?.uri && chunk.web?.title) {
          sources.push({ title: chunk.web.title, url: chunk.web.uri });
        }
      });
    }

    const uniqueSources = Array.from(new Map(sources.map(s => [s.url, s])).values());

    return {
      introText: text,
      sources: uniqueSources,
    };
  } catch (error) {
    console.error("Suchfehler:", error);
    return {
      introText: "Die Suche ist derzeit nicht verfügbar. Bitte prüfen Sie Ihre API-Konfiguration.",
      sources: [],
    };
  }
};

// 3. KI-Berater Chat
export const getAIAdvisorResponse = async (history: {role: string, parts: {text: string}[]}[], message: string) => {
  try {
    const chat = ai.chats.create({
      // Upgraded to pro model for complex legal/advisory reasoning
      model: "gemini-3-pro-preview",
      config: {
        systemInstruction: "Du bist ein Experte für deutsches Immobilienrecht (WEG-Reform, Mietrecht). Gib präzise, professionelle Ratschläge für Eigentümer. Disclaimer: Du bist eine KI, kein Anwalt.",
      },
      history: history
    });

    const result = await chat.sendMessage({ message });
    return result.text || "Entschuldigung, ich konnte keine Antwort generieren.";
  } catch (error) {
    console.error("Chat-Fehler:", error);
    return "Verbindungsprobleme. Bitte versuchen Sie es später erneut.";
  }
};

