import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../App';
import { db, COLLECTIONS, addDocument } from '../services/firebase';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { ForumThread } from '../types';

const CATEGORIES = ['Recht & Urteile', 'Software & Tech', 'Best Practice', 'Handwerker & Services', 'Off-Topic'];

const Forum = () => {
  const { user } = useContext(AuthContext);
  const [threads, setThreads] = useState<ForumThread[]>([]);
  const [selectedCategory, setSelectedCategory] = useState('Alle');
  const [search, setSearch] = useState('');
  const [isFocusMode, setIsFocusMode] = useState(false);

  // Modals
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  // New Topic Form State
  const [newTopic, setNewTopic] = useState({ title: '', category: CATEGORIES[0], content: '' });

  // Fetch Threads from Firestore
  useEffect(() => {
    const q = query(collection(db, COLLECTIONS.THREADS), orderBy("createdAt", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
        const data = snapshot.docs.map(doc => {
            const d = doc.data();
            return {
                id: doc.id,
                ...d,
                date: d.createdAt ? new Date(d.createdAt.toDate()).toLocaleDateString() : 'Neu'
            } as any;
        });
        setThreads(data);
    });
    return () => unsubscribe();
  }, []);

  const handleReport = (e: React.MouseEvent, threadTitle: string) => {
    e.stopPropagation();
    alert(`Vielen Dank. Der Thread "${threadTitle}" wurde zur Moderation gemeldet.`);
  };

  const handleCreateThread = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) {
      alert("Bitte melden Sie sich an, um ein Thema zu erstellen.");
      return;
    }

    const newThreadData = {
        title: newTopic.title,
        author: user.name,
        authorId: user.id,
        category: newTopic.category,
        content: newTopic.content,
        replies: 0,
        views: 0,
        hasRead: false
    };

    try {
        await addDocument(COLLECTIONS.THREADS, newThreadData);
        setIsCreateModalOpen(false);
        setNewTopic({ title: '', category: CATEGORIES[0], content: '' });
    } catch (err) {
        console.error("Error creating thread:", err);
    }
  };

  const filteredThreads = threads.filter(t => {
    const matchesCategory = selectedCategory === 'Alle' || t.category === selectedCategory;
    const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="bg-slate-50 min-h-screen py-12 transition-all duration-500">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black text-slate-900 mb-2 tracking-tight">Manager Exchange</h1>
            <p className="text-slate-500 font-medium">Die exklusive Community für verifizierte Hausverwalter.</p>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setIsFocusMode(!isFocusMode)}
              title={isFocusMode ? "Normalansicht" : "Fokusmodus aktivieren"}
              className={`p-3 rounded-2xl border transition-all ${isFocusMode ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
              </svg>
            </button>
            <button 
              onClick={() => setIsCreateModalOpen(true)}
              className="bg-gradient-to-r from-indigo-600 to-purple-600 text-white px-8 py-3 rounded-2xl font-bold shadow-xl shadow-indigo-200/50 hover:shadow-indigo-300/60 hover:-translate-y-0.5 transition-all flex items-center gap-2 active:scale-95"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              Neues Thema erstellen
            </button>
          </div>
        </div>

        <div className="grid lg:grid-cols-12 gap-8">
          {/* Left Sidebar */}
          {!isFocusMode && (
            <div className="lg:col-span-3 space-y-6 animate-in fade-in slide-in-from-left-4 duration-500">
              <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Kategorien</h3>
                <div className="space-y-2">
                  <button 
                    onClick={() => setSelectedCategory('Alle')}
                    className={`w-full text-left px-4 py-2.5 rounded-xl text-sm font-bold transition-all ${selectedCategory === 'Alle' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    Alle Themen
