                <div className="space-y-4 font-mono">
                  {MATCHING_STEPS.map((step, idx) => (
                    <div key={step.id} className={`flex items-center gap-4 text-xs transition-opacity duration-300 ${idx < currentStep ? 'opacity-100' : 'opacity-20'}`}>
