import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../App';
import { db, COLLECTIONS, addDocument } from '../services/firebase';
import { collection, onSnapshot, query, orderBy, where, doc, updateDoc, increment } from 'firebase/firestore';
import { ForumThread, ForumReply } from '../types';

const CATEGORIES = ['Recht & Urteile', 'Software & Tech', 'Best Practice', 'Handwerker & Services', 'Off-Topic'];

const Forum = () => {
  const { user } = useContext(AuthContext);
  const [threads, setThreads] = useState<ForumThread[]>([]);
  const [selectedThread, setSelectedThread] = useState<ForumThread | null>(null);
  const [replies, setReplies] = useState<ForumReply[]>([]);
  const [newReplyText, setNewReplyText] = useState('');

  const [selectedCategory, setSelectedCategory] = useState('Alle');
  const [search, setSearch] = useState('');
  const [isFocusMode, setIsFocusMode] = useState(false);

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newTopic, setNewTopic] = useState({ title: '', category: CATEGORIES[0], content: '' });

  // Fetch Threads
  useEffect(() => {
    const q = query(collection(db, COLLECTIONS.THREADS), orderBy("createdAt", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
        const data = snapshot.docs.map(doc => {
            const d = doc.data();
            return {
                id: doc.id,
                ...d,
                date: d.createdAt ? new Date(d.createdAt.toDate()).toLocaleDateString() : 'Neu'
            } as any;
        });
        setThreads(data);
    });
    return () => unsubscribe();
  }, []);

  // Fetch Replies when a thread is selected
  useEffect(() => {
    if (!selectedThread) {
      setReplies([]);
      return;
    }

    const q = query(
      collection(db, COLLECTIONS.REPLIES), 
      where("threadId", "==", selectedThread.id),
      orderBy("createdAt", "asc")
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      } as ForumReply));
      setReplies(data);
    });

    // Mark view
    updateDoc(doc(db, COLLECTIONS.THREADS, selectedThread.id), {
      views: increment(1)
    });

    return () => unsubscribe();
  }, [selectedThread]);

  const handleCreateThread = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    try {
        await addDocument(COLLECTIONS.THREADS, {
            title: newTopic.title,
            author: user.name,
            authorId: user.id,
            category: newTopic.category,
            content: newTopic.content,
            replies: 0,
            views: 0
        });
        setIsCreateModalOpen(false);
        setNewTopic({ title: '', category: CATEGORIES[0], content: '' });
    } catch (err) { console.error(err); }
  };

  const handlePostReply = async () => {
    if (!user || !selectedThread || !newReplyText.trim()) return;
    try {
      await addDocument(COLLECTIONS.REPLIES, {
        threadId: selectedThread.id,
        author: user.name,
        authorId: user.id,
        content: newReplyText
      });
      await updateDoc(doc(db, COLLECTIONS.THREADS, selectedThread.id), {
        replies: increment(1),
        lastActivity: new Date()
      });
      setNewReplyText('');
    } catch (err) { console.error(err); }
  };

  const filteredThreads = threads.filter(t => {
    const matchesCategory = selectedCategory === 'Alle' || t.category === selectedCategory;
    const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="bg-slate-50 min-h-screen py-12 transition-all duration-500">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Detailansicht Modal */}
        {selectedThread && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-fade-in">
             <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-fade-in-up">
                <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                   <div>
                     <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-3 py-1 rounded-full mb-2 inline-block">
                        {selectedThread.category}
                     </span>
                     <h2 className="text-2xl font-black text-slate-900">{selectedThread.title}</h2>
                   </div>
                   <button onClick={() => setSelectedThread(null)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
                      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                   </button>
                </div>

                <div className="flex-1 overflow-y-auto p-10 space-y-10 custom-scrollbar">
                   {/* Hauptbeitrag */}
                   <div className="flex gap-6">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-600 flex items-center justify-center text-white font-black text-xl shrink-0 shadow-lg">
                        {selectedThread.author[0]}
                      </div>
                      <div className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 flex-1">
                         <div className="flex justify-between mb-4">
                            <span className="font-bold text-slate-900">{selectedThread.author}</span>
                            <span className="text-xs text-slate-400 font-medium">Veröffentlicht am {(selectedThread as any).date}</span>
                         </div>
                         <p className="text-slate-700 leading-relaxed whitespace-pre-wrap">{selectedThread.content}</p>
                      </div>
                   </div>

                   {/* Trenner */}
                   <div className="flex items-center gap-4 text-slate-300">
                      <div className="h-px bg-slate-200 flex-1"></div>
                      <span className="text-[10px] font-black uppercase tracking-[0.2em]">{replies.length} Antworten</span>
                      <div className="h-px bg-slate-200 flex-1"></div>
                   </div>

                   {/* Antworten Liste */}
                   <div className="space-y-6">
                      {replies.map(reply => (
                        <div key={reply.id} className="flex gap-6 animate-fade-in">
                           <div className="w-10 h-10 rounded-xl bg-slate-200 flex items-center justify-center text-slate-600 font-bold shrink-0">
                             {reply.author[0]}
                           </div>
                           <div className="bg-white p-6 rounded-[1.5rem] border border-slate-100 shadow-sm flex-1">
                              <div className="flex justify-between mb-2">
                                 <span className="text-sm font-black text-slate-800">{reply.author}</span>
                                 <span className="text-[10px] text-slate-400 font-bold">{reply.createdAt ? new Date(reply.createdAt.toDate()).toLocaleDateString() : 'Jetzt'}</span>
                              </div>
                              <p className="text-slate-600 text-sm leading-relaxed">{reply.content}</p>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>

                {/* Antwort schreiben Sektion */}
                <div className="p-8 border-t border-slate-100 bg-white">
                   <div className="flex gap-4">
                      <textarea 
                        value={newReplyText}
                        onChange={(e) => setNewReplyText(e.target.value)}
                        placeholder="Schreiben Sie eine hilfreiche Antwort..."
                        className="flex-1 bg-slate-50 border-0 rounded-2xl px-6 py-4 text-slate-900 ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-600 transition-all resize-none font-medium h-14 min-h-[56px] focus:h-32"
                      />
                      <button 
                        onClick={handlePostReply}
                        disabled={!newReplyText.trim()}
                        className="bg-indigo-600 text-white px-8 h-14 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-20 transition-all"
                      >
                        Antworten
                      </button>
                   </div>
                </div>
             </div>
          </div>
        )}

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black text-slate-900 mb-2 tracking-tight">Manager Exchange</h1>
            <p className="text-slate-500 font-medium text-lg">Die exklusive Community für verifizierte Hausverwalter.</p>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => setIsFocusMode(!isFocusMode)}
              className={`p-3 rounded-2xl border transition-all ${isFocusMode ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg' : 'bg-white text-slate-600 hover:bg-slate-50'}`}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            </button>
            <button 
              onClick={() => setIsCreateModalOpen(true)}
              className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold shadow-xl hover:bg-indigo-600 transition-all active:scale-95 flex items-center gap-2"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
              Thema erstellen
            </button>
          </div>
        </div>

        <div className="grid lg:grid-cols-12 gap-8">
          {!isFocusMode && (
            <div className="lg:col-span-3 space-y-6">
              <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6">Kategorien</h3>
                <div className="space-y-2">
                  <button onClick={() => setSelectedCategory('Alle')} className={`w-full text-left px-4 py-2.5 rounded-xl text-sm font-bold transition-all ${selectedCategory === 'Alle' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-50'}`}>Alle Themen</button>
                  {CATEGORIES.map(cat => (
                    <button key={cat} onClick={() => setSelectedCategory(cat)} className={`w-full text-left px-4 py-2.5 rounded-xl text-sm font-bold transition-all ${selectedCategory === cat ? 'bg-indigo-50 text-indigo-600' : 'text-slate-600 hover:bg-slate-50'}`}>{cat}</button>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className={`${isFocusMode ? 'lg:col-span-12' : 'lg:col-span-9'} space-y-4`}>
            <div className="bg-white p-2 rounded-2xl border border-slate-200 shadow-sm flex gap-2">
                <div className="flex-1 flex items-center px-4 gap-3">
                    <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    <input type="text" placeholder="Beiträge durchsuchen..." className="w-full bg-transparent border-none focus:ring-0 text-sm font-medium" value={search} onChange={(e) => setSearch(e.target.value)} />
                </div>
            </div>

            <div className="space-y-3">
              {filteredThreads.map(thread => (
                <div key={thread.id} onClick={() => setSelectedThread(thread)} className="bg-white p-6 rounded-3xl border border-slate-200 hover:border-indigo-300 transition-all cursor-pointer group shadow-sm relative">
                  <div className="flex justify-between items-start gap-4">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-wider">{thread.category}</span>
                        <span className="text-[10px] text-slate-400 font-bold">{(thread as any).date}</span>
                      </div>
                      <h3 className="text-lg font-extrabold text-slate-900 group-hover:text-indigo-600 transition-colors mb-2">{thread.title}</h3>
                      <div className="flex items-center gap-2">
                        <div className="w-5 h-5 bg-slate-200 rounded-full flex items-center justify-center text-[10px] font-bold text-slate-500 uppercase">{thread.author[0]}</div>
                        <span className="text-xs font-bold text-slate-500">{thread.author}</span>
                      </div>
                    </div>
                    <div className="flex gap-4 text-center">
                      <div className="px-3 py-1 bg-slate-50 rounded-xl">
                        <p className="text-sm font-black text-slate-700">{thread.replies}</p>
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Antworten</p>
                      </div>
                      <div className="px-3 py-1 bg-slate-50 rounded-xl">
                        <p className="text-sm font-black text-slate-700">{thread.views}</p>
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">Aufrufe</p>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Thread Creation Modal (verkürzt für Platz) */}
      {isCreateModalOpen && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10">
              <h2 className="text-3xl font-black mb-8">Neues Thema</h2>
              <form onSubmit={handleCreateThread} className="space-y-6">
                <input required placeholder="Titel" className="w-full p-4 bg-slate-50 rounded-xl" value={newTopic.title} onChange={e => setNewTopic({...newTopic, title: e.target.value})} />
                <textarea required placeholder="Inhalt" className="w-full h-40 p-4 bg-slate-50 rounded-xl" value={newTopic.content} onChange={e => setNewTopic({...newTopic, content: e.target.value})} />
                <div className="flex gap-4">
                   <button type="button" onClick={() => setIsCreateModalOpen(false)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">Abbrechen</button>
                   <button type="submit" className="flex-1 py-4 bg-indigo-600 text-white rounded-xl font-bold">Veröffentlichen</button>
                </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

