import React, { useEffect, useState, useContext, useRef } from 'react';
import { AuthContext } from '../App';
import { getMessages, sendMessage, markMessageRead } from '../services/dataService';
import { Message } from '../types';

const Messaging = () => {
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState<Message[]>([]);
  const [replyText, setReplyText] = useState('');
  const [selectedMsg, setSelectedMsg] = useState<Message | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (user) {
      const fetchMessages = () => {
        // In realer App würde hier eine echte Firestore-Query genutzt werden
        getMessages(user.id).then(setMessages);
      };

      fetchMessages();
      const interval = setInterval(fetchMessages, 10000); // Seltener poller, in echt onSnapshot
      return () => clearInterval(interval);
    }
  }, [user]);

  useEffect(() => {
    if (selectedMsg && !selectedMsg.read && selectedMsg.receiverId === user?.id) {
      markMessageRead(selectedMsg.id).then(() => {
        setMessages(prev => prev.map(m => m.id === selectedMsg.id ? { ...m, read: true } : m));
      });
    }
    scrollRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  }, [selectedMsg, user?.id]);

  const handleReply = async () => {
    if (!user || !selectedMsg || !replyText.trim()) return;

    const targetUserId = selectedMsg.senderId === user.id ? selectedMsg.receiverId : selectedMsg.senderId;

    await sendMessage({
      senderId: user.id,
      senderName: user.name,
      receiverId: targetUserId,
      receiverName: selectedMsg.senderId === user.id ? selectedMsg.receiverName : selectedMsg.senderName,
      subject: selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`,
      content: replyText,
    });

    setReplyText('');
    alert("Antwort wurde erfolgreich versendet!");
  };

  const formatTimeShort = (ts: any) => {
    if (!ts) return "Gerade";
    const date = ts.toDate ? ts.toDate() : new Date(ts);
    const now = new Date();
    if (date.toDateString() === now.toDateString()) {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }
    return date.toLocaleDateString([], { day: '2-digit', month: '2-digit' });
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 h-[calc(100vh-6rem)]">
      <div className="flex h-full bg-white rounded-[2.5rem] overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.05)] border border-slate-100">

        {/* Seitenleiste: Posteingang */}
        <div className="w-1/3 min-w-[340px] border-r border-slate-100 flex flex-col bg-slate-50/50">
          <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-white">
            <h2 className="font-black text-2xl text-slate-900 tracking-tighter">Posteingang</h2>
            <div className="bg-indigo-600 text-white text-[10px] font-black px-2.5 py-1 rounded-full uppercase tracking-widest shadow-lg shadow-indigo-200">
              {messages.filter(m => !m.read && m.receiverId === user?.id).length} Neu
            </div>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
            {messages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full text-slate-400 p-8 text-center opacity-40">
                <svg className="w-16 h-16 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" /></svg>
                <p className="font-bold">Noch keine Konversationen</p>
              </div>
            )}
            {messages.map(msg => {
              const isUnread = !msg.read && msg.receiverId === user?.id;
              const isMe = msg.senderId === user?.id;
              return (
                <div 
                  key={msg.id}
                  onClick={() => setSelectedMsg(msg)}
                  className={`p-5 rounded-[1.8rem] cursor-pointer transition-all relative group ${
                      selectedMsg?.id === msg.id 
                      ? 'bg-white shadow-xl border border-indigo-50' 
                      : 'hover:bg-white border border-transparent'
                  }`}
                >
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-2 max-w-[70%]">
                      {isUnread && <span className="w-2 h-2 bg-indigo-600 rounded-full"></span>}
                      <span className={`font-bold text-sm truncate ${isUnread ? 'text-slate-900' : 'text-slate-600'}`}>
                        {isMe ? `An: ${msg.receiverName}` : msg.senderName}
                      </span>
                    </div>
                    <span className="text-[10px] font-black text-slate-400">{formatTimeShort(msg.timestamp)}</span>
                  </div>
                  <p className={`text-sm truncate ${isUnread ? 'font-black' : 'font-medium text-slate-500'}`}>{msg.subject}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Hauptansicht: Nachrichteninhalte */}
        <div className="flex-1 flex flex-col bg-white">
          {selectedMsg ? (
            <>
              <div className="p-10 border-b border-slate-50">
                 <h2 className="text-3xl font-black text-slate-900 tracking-tight mb-2">{selectedMsg.subject}</h2>
                 <div className="flex items-center gap-3 text-sm text-slate-500 font-medium">
                    <span>Von: <span className="font-bold text-slate-800">{selectedMsg.senderName}</span></span>
                    <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                    <span>Datum: <span className="text-slate-900 font-bold">{formatTimeShort(selectedMsg.timestamp)}</span></span>
                 </div>
              </div>
              <div ref={scrollRef} className="flex-1 p-10 overflow-y-auto space-y-8">
                <div className="max-w-3xl">
                    <div className="bg-slate-50 p-10 rounded-[2.5rem] border border-slate-100 text-slate-800 leading-relaxed whitespace-pre-wrap text-lg font-light">
                        {selectedMsg.content}
                    </div>
                </div>
              </div>

              <div className="p-8 border-t border-slate-50 bg-slate-50/30">
                <div className="max-w-4xl mx-auto flex gap-4">
                  <textarea 
                    rows={1}
                    value={replyText} 
                    onChange={e => setReplyText(e.target.value)}
                    placeholder="Schreiben Sie Ihre Antwort..."
                    className="flex-1 bg-white border border-slate-200 rounded-2xl px-6 py-4 text-slate-900 focus:ring-2 focus:ring-indigo-500 transition-all outline-none resize-none"
                  />
                  <button onClick={handleReply} disabled={!replyText.trim()} className="bg-slate-900 text-white px-8 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-indigo-600 transition-all shadow-xl disabled:opacity-20">Senden</button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-slate-300">
               <svg className="w-24 h-24 mb-6 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
               <p className="font-black text-2xl tracking-tighter uppercase">Nachrichtenzentrum</p>
               <p className="text-sm font-bold">Wählen Sie einen Chat aus, um zu antworten.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

