// --- AUTHENTICATION (Mit Speed-Test) ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  console.time("Login-Total");
  try {
    console.time("Login-Auth");
    const userCredential = await signInWithEmailAndPassword(auth, email, password);
    console.timeEnd("Login-Auth"); 

    const uid = userCredential.user.uid;

    console.time("Login-Firestore");
    const userDoc = await getDoc(doc(db, "users", uid));
    console.timeEnd("Login-Firestore"); 

    console.timeEnd("Login-Total");

    if (userDoc.exists()) {
      return { id: userDoc.id, ...userDoc.data() } as User;
    } else {
      // Fallback User
      return { 
        id: uid, 
        email: email, 
        name: email.split('@')[0], 
        role: 'seeker',
        avatar: '',
        bio: ''
      };
    }
  } catch (error) {
    console.error("Login Error:", error);
    throw error;
  }
};

export const logoutUser = async () => {
  try {
    await signOut(auth);
  } catch (error) {
    console.error("Logout Error:", error);
  }
};

export const getUserProfile = async (uid: string): Promise<User | null> => {
  try {
    const userDoc = await getDoc(doc(db, "users", uid));
    if (userDoc.exists()) {
      return { id: userDoc.id, ...userDoc.data() } as User;
    }
    return null;
  } catch (error) {
    console.error("Error fetching user profile:", error);
    return null;
  }
};

// Fix: Updated registerUser to accept avatar and bio arguments to match its usage in Login.tsx
export const registerUser = async (email: string, password: string, name: string, role: UserRole, avatar?: string, bio?: string): Promise<User> => {
  try {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    const uid = userCredential.user.uid;
    const newUser: User = { 
      id: uid, 
      email, 
      name, 
      role,
      avatar: avatar || '',
      bio: bio || ''
    };
    await setDoc(doc(db, "users", uid), newUser);
    return newUser;
  } catch (error) {
    console.error("Registration Error:", error);
    throw error;
  }
};

// --- INQUIRIES ---

export const createInquiry = async (inquiryData: Omit<Inquiry, 'id' | 'createdAt'>) => {
  try {
    // Wir nutzen hier 'offen' als Standard, passend zu deinem Type
    const docRef = await addDoc(collection(db, "inquiries"), {
      ...inquiryData,
      createdAt: serverTimestamp(),
      status: inquiryData.status || 'offen' 
    });
    return docRef.id;
  } catch (error) {
    console.error("Error creating inquiry:", error);
    throw error;
  }
};

export const getInquiries = async (): Promise<Inquiry[]> => {
  try {
    const q = query(collection(db, "inquiries"), orderBy("createdAt", "desc"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ 
      id: doc.id, 
      ...doc.data() 
    } as Inquiry));
  } catch (error) {
    console.error("Error getting inquiries:", error);
    return [];
  }
};

// Angepasst an deine Status-Typen ('neu' | 'kontaktiert' | 'archiviert' | 'offen' ...)
export const updateInquiryStatus = async (inquiryId: string, newStatus: Inquiry['status']) => {
  try {
    const inquiryRef = doc(db, "inquiries", inquiryId);
    await updateDoc(inquiryRef, { status: newStatus });
  } catch (error) {
    console.error("Error updating status:", error);
    throw error;
  }
};

// --- FORUM ---

export const getForumThreads = async (): Promise<ForumThread[]> => {
  try {
    // Nutzt 'lastActivity' wie in deinem Type definiert
    const q = query(collection(db, "forum_threads"), orderBy("lastActivity", "desc"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ 
      id: doc.id, 
      ...doc.data() 
    } as ForumThread));
  } catch (error) {
    console.error("Error getting forum threads:", error);
    return [];
  }
};

export const createThread = async (threadData: Omit<ForumThread, 'id' | 'createdAt' | 'replies' | 'views'>) => {
  try {
    await addDoc(collection(db, "forum_threads"), {
      ...threadData,
      createdAt: serverTimestamp(),
      lastActivity: serverTimestamp(),
      replies: 0, // In deinem Type heißt es 'replies', nicht 'repliesCount'
      views: 0
    });
  } catch (error) {
    console.error("Error creating thread:", error);
    throw error;
  }
};

