import React, { useEffect, useState, useContext, useRef } from 'react';
import { AuthContext } from '../App';
import { getMessages, sendMessage, markMessageRead } from '../services/dataService';
import { Message } from '../types';

const Messaging = () => {
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState<Message[]>([]);
  const [replyText, setReplyText] = useState('');
  const [selectedMsg, setSelectedMsg] = useState<Message | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // In einer echten App würde man hier onSnapshot für Echtzeit nutzen.
  // Hier simulieren wir den Abruf.
  useEffect(() => {
    if (user) {
      const fetchMessages = async () => {
        const msgs = await getMessages(user.id);
        // Wir sortieren lokal nach Zeitstempel absteigend für die Liste
        setMessages(msgs.sort((a, b) => {
          const t1 = a.timestamp?.seconds || 0;
          const t2 = b.timestamp?.seconds || 0;
          return t2 - t1;
        }));
      };

      fetchMessages();
      const interval = setInterval(fetchMessages, 5000);
      return () => clearInterval(interval);
    }
  }, [user]);

  useEffect(() => {
    if (selectedMsg && !selectedMsg.read && selectedMsg.receiverId === user?.id) {
      markMessageRead(selectedMsg.id).then(() => {
        setMessages(prev => prev.map(m => m.id === selectedMsg.id ? { ...m, read: true } : m));
      });
    }
    scrollRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  }, [selectedMsg, user?.id]);

  const handleReply = async () => {
    if (!user || !selectedMsg || !replyText.trim()) return;

    const targetUserId = selectedMsg.senderId === user.id ? selectedMsg.receiverId : selectedMsg.senderId;
    const targetUserName = selectedMsg.senderId === user.id ? selectedMsg.receiverName : selectedMsg.senderName;

    try {
      await sendMessage({
        senderId: user.id,
        senderName: user.name,
        receiverId: targetUserId,
        receiverName: targetUserName,
        subject: selectedMsg.subject.startsWith('Re:') ? selectedMsg.subject : `Re: ${selectedMsg.subject}`,
        content: replyText,
      });

      setReplyText('');
      // In dieser Demo-App zeigen wir ein Toast/Alert
      const toast = document.createElement('div');
      toast.className = "fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold shadow-2xl animate-fade-in-up z-[200]";
      toast.innerText = "Antwort wurde gesendet! ✓";
      document.body.appendChild(toast);
      setTimeout(() => toast.remove(), 3000);
    } catch (err) {
      console.error(err);
    }
  };

  const formatFullTime = (ts: any) => {
    if (!ts) return "Gerade eben";
    const date = ts.toDate ? ts.toDate() : new Date(ts);
    return date.toLocaleString('de-DE', { 
      day: '2-digit', 
      month: 'long', 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  const formatShortTime = (ts: any) => {
    if (!ts) return "Jetzt";
    const date = ts.toDate ? ts.toDate() : new Date(ts);
    const now = new Date();
    const diff = (now.getTime() - date.getTime()) / 1000;

    if (diff < 60) return "Gerade eben";
    if (diff < 3600) return `${Math.floor(diff / 60)} Min.`;

    if (date.toDateString() === now.toDateString()) {
      return date.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
    }
    return date.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit' });
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 h-[calc(100vh-6rem)]">
      <div className="flex h-full bg-white rounded-[3rem] overflow-hidden shadow-[0_32px_80px_rgba(0,0,0,0.06)] border border-slate-100">

        {/* Posteingang Sidebar */}
        <div className="w-full md:w-[400px] border-r border-slate-50 flex flex-col bg-slate-50/30">
          <div className="p-8 pb-6">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-3xl font-black text-slate-900 tracking-tighter">Postfach</h2>
              <div className="w-10 h-10 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
              </div>
            </div>
            <div className="relative">
               <input 
                 type="text" 
                 placeholder="Nachrichten durchsuchen..." 
                 className="w-full bg-white border border-slate-100 rounded-2xl px-5 py-3 text-sm font-medium focus:ring-2 focus:ring-indigo-500/20 transition-all outline-none"
               />
            </div>
          </div>

          <div className="flex-1 overflow-y-auto px-4 pb-8 space-y-2 custom-scrollbar">
            {messages.map(msg => {
              const isUnread = !msg.read && msg.receiverId === user?.id;
              const isActive = selectedMsg?.id === msg.id;
              const isMe = msg.senderId === user?.id;

              return (
                <div 
                  key={msg.id}
                  onClick={() => setSelectedMsg(msg)}
                  className={`p-5 rounded-[2rem] cursor-pointer transition-all relative group border-2 ${
                    isActive 
                    ? 'bg-white border-indigo-100 shadow-xl shadow-indigo-500/5 translate-x-1' 
                    : 'bg-transparent border-transparent hover:bg-white/50 hover:border-slate-100'
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-3">
                      {isUnread && <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full shadow-[0_0_10px_rgba(79,70,229,0.5)]"></div>}
                      <span className={`text-sm font-black truncate max-w-[150px] ${isActive ? 'text-indigo-600' : 'text-slate-900'}`}>
                        {isMe ? `An: ${msg.receiverName}` : msg.senderName}
                      </span>
                    </div>
                    <span className="text-[10px] font-bold text-slate-400 whitespace-nowrap">{formatShortTime(msg.timestamp)}</span>
                  </div>
                  <div className="flex justify-between items-center gap-2">
                    <p className={`text-xs truncate flex-1 ${isUnread ? 'text-slate-900 font-bold' : 'text-slate-500 font-medium'}`}>
                      {msg.subject}
                    </p>
                    {isMe && (
                      <div className="flex items-center">
                        <svg className={`w-4 h-4 ${msg.read ? 'text-blue-500' : 'text-slate-300'}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                          <path d="M5 13l4 4L19 7" strokeLinecap="round" strokeLinejoin="round" />
                          {msg.read && <path d="M10 13l4 4L24 7" strokeLinecap="round" strokeLinejoin="round" transform="translate(-5, 0)" />}
                        </svg>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Chat Ansicht */}
        <div className="flex-1 flex flex-col bg-white">
          {selectedMsg ? (
            <>
              <div className="p-8 border-b border-slate-50 flex justify-between items-center">
                <div className="flex items-center gap-5">
                   <div className="w-14 h-14 bg-slate-100 rounded-[1.2rem] flex items-center justify-center text-slate-400 font-black text-xl border border-slate-100">
                     {selectedMsg.senderName[0]}
                   </div>
                   <div>
                     <h3 className="text-xl font-black text-slate-900 tracking-tight">{selectedMsg.subject}</h3>
                     <p className="text-xs text-slate-400 font-bold uppercase tracking-widest flex items-center gap-2">
                       {selectedMsg.senderName}
                       <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                       Online
                     </p>
                   </div>
                </div>
                <div className="flex gap-2">
                   <button className="p-3 text-slate-400 hover:bg-slate-50 rounded-xl transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 12h.01M12 12h.01M19 12h.01M6 12a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0zm7 0a1 1 0 11-2 0 1 1 0 012 0z" /></svg></button>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto p-10 space-y-8 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] bg-fixed opacity-95">
                 <div className="flex flex-col space-y-6">
                    <div className="flex justify-center">
                       <span className="bg-slate-100 text-slate-400 text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-widest">
                         {formatFullTime(selectedMsg.timestamp)}
                       </span>
                    </div>

                    <div className={`flex gap-4 ${selectedMsg.senderId === user?.id ? 'flex-row-reverse' : ''}`}>
                       <div className={`max-w-[80%] p-8 rounded-[2.5rem] shadow-sm border ${
                         selectedMsg.senderId === user?.id 
                         ? 'bg-indigo-600 text-white rounded-tr-none border-indigo-500' 
                         : 'bg-white text-slate-800 rounded-tl-none border-slate-100'
                       }`}>
                          <p className="text-lg leading-relaxed whitespace-pre-wrap font-medium">
                            {selectedMsg.content}
                          </p>
                          <div className={`flex items-center gap-2 mt-4 text-[10px] font-bold ${selectedMsg.senderId === user?.id ? 'text-indigo-200' : 'text-slate-400'}`}>
                             {formatShortTime(selectedMsg.timestamp)}
                             {selectedMsg.senderId === user?.id && (
                                <svg className={`w-4 h-4 ${selectedMsg.read ? 'text-blue-300' : 'text-indigo-300'}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                                  <path d="M5 13l4 4L19 7" strokeLinecap="round" strokeLinejoin="round" />
                                  {selectedMsg.read && <path d="M10 13l4 4L24 7" strokeLinecap="round" strokeLinejoin="round" transform="translate(-5, 0)" />}
                                </svg>
                             )}
                          </div>
                       </div>
                    </div>
                 </div>
                 <div ref={scrollRef}></div>
              </div>

              <div className="p-8 bg-white border-t border-slate-50">
                 <div className="max-w-4xl mx-auto flex items-end gap-4 bg-slate-50 p-2 rounded-[2.5rem] ring-1 ring-slate-100 focus-within:ring-2 focus-within:ring-indigo-500 transition-all">
                    <textarea 
                      rows={1}
                      value={replyText}
                      onChange={e => setReplyText(e.target.value)}
                      placeholder="Ihre Nachricht schreiben..."
                      className="flex-1 bg-transparent border-0 px-6 py-4 text-slate-900 focus:ring-0 outline-none resize-none font-medium h-14 min-h-[56px] focus:h-32 transition-all"
                    />
                    <button 
                      onClick={handleReply}
                      disabled={!replyText.trim()}
                      className="bg-indigo-600 text-white w-14 h-14 rounded-[1.8rem] flex items-center justify-center shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-20 transition-all active:scale-90"
                    >
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
                    </button>
                 </div>
              </div>
            </>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-center p-20">
               <div className="w-32 h-32 bg-slate-50 rounded-[3rem] flex items-center justify-center text-slate-200 mb-8 border border-slate-100">
                  <svg className="w-16 h-16" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
               </div>
               <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Nachrichtenzentrum</h3>
               <p className="text-slate-500 font-medium max-w-xs">Wählen Sie eine Konversation aus der Liste, um die Details anzuzeigen und zu antworten.</p>
            </div>
