import { GoogleGenAI, Type } from "@google/genai";
import { InquiryAnalysis, ManagerSearchResult } from "../types";

// Initializing GoogleGenAI client with apiKey in a named parameter.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzePropertyRequirement = async (formData: any): Promise<InquiryAnalysis> => {
  // Added condition field to the analysis prompt for more accurate results.
  const prompt = `
    Analysiere diese deutsche Immobilien-Anfrage für eine Hausverwaltung.
    Stadt: ${formData.city}
    Einheiten: ${formData.units}
    Typ: ${formData.propertyType}
    Baujahr: ${formData.buildingAge}
    Zustand: ${formData.condition}
    Beschreibung: ${formData.description}

    Antworte im JSON-Format auf Deutsch. 
    1. Erstelle eine professionelle Zusammenfassung (summary).
    2. Extrahiere Kernanforderungen (keyRequirements) als Liste.
    3. Schätze den Verwaltungsaufwand (estimatedEffort: Niedrig, Mittel, Hoch).
    4. Gib einen kurzen Hinweis zum relevanten deutschen Recht (z.B. WEG-Reform 2020) (legalAdviceSnippet).
    5. Schlagwörter (recommendedTags).
  `;

  try {
    // Calling generateContent with gemini-3-pro-preview for complex reasoning tasks.
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            keyRequirements: { type: Type.ARRAY, items: { type: Type.STRING } },
            estimatedEffort: { type: Type.STRING, enum: ["Niedrig", "Mittel", "Hoch"] },
            legalAdviceSnippet: { type: Type.STRING },
            recommendedTags: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "keyRequirements", "estimatedEffort", "legalAdviceSnippet", "recommendedTags"],
        },
      },
    });

    // Accessing response.text property directly as a string.
    return JSON.parse(response.text || "{}") as InquiryAnalysis;
  } catch (error) {
    console.error("KI-Fehler:", error);
    return {
      summary: "Manuelle Analyse erforderlich.",
      keyRequirements: ["Datenprüfung"],
      estimatedEffort: "Mittel",
      legalAdviceSnippet: "Bitte prüfen Sie die aktuelle WEG-Gesetzgebung.",
      recommendedTags: ["In Prüfung"]
    };
  }
};

export const searchPropertyManagers = async (city: string): Promise<ManagerSearchResult> => {
  // Using googleSearch tool for real-time web grounding.
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Finde die 3 besten Hausverwaltungen in ${city}, Deutschland. Nutze Google Suche. Liste Gründe für die Empfehlung auf.`,
    config: { tools: [{ googleSearch: {} }] },
  });

  const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
    title: c.web?.title || "Quelle",
    url: c.web?.uri || "#"
  })) || [];

  return {
    // response.text provides the generated text content.
    introText: response.text || "Keine Ergebnisse gefunden.",
    sources: sources.filter(s => s.url !== "#"),
  };
};

export const getAIAdvisorResponse = async (history: any[], message: string) => {
  const chat = ai.chats.create({
    model: "gemini-3-pro-preview",
    config: {
      systemInstruction: "Du bist 'HausMatch Expert', ein KI-Berater für deutsches Immobilienrecht. Beziehe dich auf WEG, Mietrecht und BGB. Sei professionell und präzise. Ersetze keine Rechtsberatung.",
    },
    history: history
  });
  const result = await chat.sendMessage({ message });
  // result.text returns the final message content as a string.
  return result.text || "Entschuldigung, ich konnte keine Antwort generieren.";
};

