import { GoogleGenAI, Type } from "@google/genai";
import { InquiryAnalysis, ManagerSearchResult, BlogArticle } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzePropertyRequirement = async (formData: any): Promise<InquiryAnalysis> => {
  const prompt = `
    Analysiere diese deutsche Immobilien-Anfrage für eine Hausverwaltung.
    Stadt: ${formData.city}
    Einheiten: ${formData.units}
    Typ: ${formData.propertyType}
    Baujahr: ${formData.buildingAge}
    Zustand: ${formData.condition}
    Beschreibung: ${formData.description}

    Antworte im JSON-Format auf Deutsch. 
    1. Erstelle eine professionelle Zusammenfassung (summary).
    2. Extrahiere Kernanforderungen (keyRequirements) als Liste.
    3. Schätze den Verwaltungsaufwand (estimatedEffort: Niedrig, Mittel, Hoch).
    4. Gib einen kurzen Hinweis zum relevanten deutschen Recht (z.B. WEG-Reform 2020) (legalAdviceSnippet).
    5. Schlagwörter (recommendedTags).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            keyRequirements: { type: Type.ARRAY, items: { type: Type.STRING } },
            estimatedEffort: { type: Type.STRING, enum: ["Niedrig", "Mittel", "Hoch"] },
            legalAdviceSnippet: { type: Type.STRING },
            recommendedTags: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["summary", "keyRequirements", "estimatedEffort", "legalAdviceSnippet", "recommendedTags"],
        },
      },
    });
    return JSON.parse(response.text || "{}") as InquiryAnalysis;
  } catch (error) {
    console.error("KI-Fehler:", error);
    return {
      summary: "Manuelle Analyse erforderlich.",
      keyRequirements: ["Datenprüfung"],
      estimatedEffort: "Mittel",
      legalAdviceSnippet: "Bitte prüfen Sie die aktuelle WEG-Gesetzgebung.",
      recommendedTags: ["In Prüfung"]
    };
  }
};

/**
 * Holt die neuesten Branchen-Nachrichten via Google Search Grounding
 */
export const fetchLatestIndustryBlog = async (): Promise<BlogArticle[]> => {
  const prompt = `
    Suche nach den aktuellsten und seriösesten Nachrichten für deutsche Immobilienverwalter (WEG-Recht, BGH Urteile Mietrecht, Heizungsgesetz GEG, energetische Sanierung) aus den letzten 7 Tagen.
    Erstelle 3 hochwertige Fachbeiträge.
    Nutze ausschließlich seriöse Quellen wie Haufe Immobilien, IVD, Bundesgesetzblatt oder Fachportale für Hausverwalter.

    Antworte im JSON-Format:
    Liste von Objekten mit:
    title: String (knackige Experten-Headline),
    summary: String (Einleitungssatz),
    fullContent: String (ausführlicher Fließtext mit Experten-Tipps),
    category: "Recht" | "Technik" | "Management" | "News",
    sources: Liste von {title: String, url: String}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              summary: { type: Type.STRING },
              fullContent: { type: Type.STRING },
              category: { type: Type.STRING },
              sources: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    title: { type: Type.STRING },
                    url: { type: Type.STRING }
                  }
                }
              }
            }
          }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    return results.map((r: any, i: number) => ({
      ...r,
      id: `ai-blog-${Date.now()}-${i}`,
      date: new Date().toLocaleDateString('de-DE'),
      isLatest: i === 0
    }));
  } catch (error) {
    console.error("Fehler beim Blog-Update:", error);
    return [];
  }
};

export const searchPropertyManagers = async (city: string): Promise<ManagerSearchResult> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Finde die 3 besten Hausverwaltungen in ${city}, Deutschland. Nutze Google Suche. Liste Gründe für die Empfehlung auf.`,
    config: { tools: [{ googleSearch: {} }] },
  });

  const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => ({
    title: c.web?.title || "Quelle",
    url: c.web?.uri || "#"
  })) || [];

  return {
    introText: response.text || "Keine Ergebnisse gefunden.",
    sources: sources.filter(s => s.url !== "#"),
  };
};

