  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signOut,
} from "firebase/auth";
import { 
  collection,
  doc,
  getDoc,
  getDocs,
  addDoc,
  setDoc,
  updateDoc,
  query,
  orderBy,
  serverTimestamp
} from "firebase/firestore";

export { auth, db };

// --- AUTHENTICATION (Mit Speed-Test) ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  console.time("Login-Total");
  try {
    console.time("Login-Auth");
    const userCredential = await signInWithEmailAndPassword(auth, email, password);
    console.timeEnd("Login-Auth"); 

    const uid = userCredential.user.uid;

    console.time("Login-Firestore");
    const userDoc = await getDoc(doc(db, "users", uid));
    console.timeEnd("Login-Firestore"); 

    console.timeEnd("Login-Total");

    if (userDoc.exists()) {
      return { id: userDoc.id, ...userDoc.data() } as User;
    } else {
      // Fallback User
      return { 
        id: uid, 
        email: email, 
        name: email.split('@')[0], 
        role: 'seeker',
        avatar: '',
        bio: ''
      };
    }
  } catch (error) {
    console.error("Login Error:", error);
    throw error;
  }
};

export const logoutUser = async () => {
  try {
    await signOut(auth);
  } catch (error) {
    console.error("Logout Error:", error);
  }
};

export const getUserProfile = async (uid: string): Promise<User | null> => {
  try {
    const userDoc = await getDoc(doc(db, "users", uid));
    if (userDoc.exists()) {
      return { id: userDoc.id, ...userDoc.data() } as User;
    }
    return null;
  } catch (error) {
    console.error("Error fetching user profile:", error);
    return null;
  }
};

// Fix: Correctly register user in Firestore
export const registerUser = async (email: string, password: string, name: string, role: UserRole, avatar?: string, bio?: string): Promise<User> => {
  try {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    const uid = userCredential.user.uid;
    const newUser: User = { 
      id: uid, 
      email, 
      name, 
      role,
      avatar: avatar || '',
      bio: bio || ''
    };
    await setDoc(doc(db, "users", uid), newUser);
    return newUser;
  } catch (error) {
    console.error("Registration Error:", error);
    throw error;
  }
};

// --- INQUIRIES ---

export const createInquiry = async (inquiryData: Omit<Inquiry, 'id' | 'createdAt'>) => {
  try {
    // Wir nutzen hier 'offen' als Standard, passend zu deinem Type
    const docRef = await addDoc(collection(db, "inquiries"), {
      ...inquiryData,
      createdAt: serverTimestamp(),
      status: inquiryData.status || 'offen' 
    });
    return docRef.id;
  } catch (error) {
    console.error("Error creating inquiry:", error);
    throw error;
  }
};

export const getInquiries = async (): Promise<Inquiry[]> => {
  try {
    const q = query(collection(db, "inquiries"), orderBy("createdAt", "desc"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ 
      id: doc.id, 
      ...doc.data() 
    } as Inquiry));
  } catch (error) {
    console.error("Error getting inquiries:", error);
    return [];
  }
};

// Angepasst an deine Status-Typen
export const updateInquiryStatus = async (inquiryId: string, newStatus: Inquiry['status']) => {
  try {
    const inquiryRef = doc(db, "inquiries", inquiryId);
    await updateDoc(inquiryRef, { status: newStatus });
  } catch (error) {
    console.error("Error updating status:", error);
    throw error;
  }
};

// --- FORUM ---

export const getForumThreads = async (): Promise<ForumThread[]> => {
  try {
    const q = query(collection(db, "forum_threads"), orderBy("lastActivity", "desc"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ 
      id: doc.id, 
      ...doc.data() 
    } as ForumThread));
  } catch (error) {
    console.error("Error getting forum threads:", error);
    return [];
  }
};

export const createThread = async (threadData: Omit<ForumThread, 'id' | 'createdAt' | 'replies' | 'views'>) => {
  try {
    await addDoc(collection(db, "forum_threads"), {
      ...threadData,
      createdAt: serverTimestamp(),
      lastActivity: serverTimestamp(),
      replies: 0,
      views: 0
    });
  } catch (error) {
    console.error("Error creating thread:", error);
    throw error;
  }
};

// --- MESSAGING ---

export const getMessages = async (userId: string): Promise<Message[]> => {
  try {
    const q = query(collection(db, "messages"), orderBy("timestamp", "desc"));
    const querySnapshot = await getDocs(q);
    const msgs = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Message));
    return msgs.filter(m => m.senderId === userId || m.receiverId === userId);
  } catch (error) {
    console.error("Error fetching messages:", error);
    return [];
  }
};

export const sendMessage = async (messageData: Omit<Message, 'id' | 'timestamp' | 'read'>) => {
  try {
    await addDoc(collection(db, "messages"), {
      ...messageData,
      timestamp: serverTimestamp(),
      read: false
    });
  } catch (error) {
    console.error("Error sending message:", error);
  }
};

export const markMessageRead = async (messageId: string) => {
  try {
    await updateDoc(doc(db, "messages", messageId), { read: true });
  } catch (error) {
    console.error("Error marking message read:", error);
  }
};

import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../App';
import { db, COLLECTIONS, addDocument } from '../services/firebase';
import { collection, onSnapshot, query, orderBy, where, doc, updateDoc, increment } from 'firebase/firestore';
import { ForumThread, ForumReply } from '../types';

const CATEGORIES = ['Recht & Urteile', 'Software & Tech', 'Best Practice', 'Handwerker & Services', 'Off-Topic'];

const Forum = () => {
  const { user } = useContext(AuthContext);
  const [threads, setThreads] = useState<ForumThread[]>([]);
  const [selectedThread, setSelectedThread] = useState<ForumThread | null>(null);
  const [replies, setReplies] = useState<ForumReply[]>([]);
  const [repliesLoading, setRepliesLoading] = useState(false);
  const [newReplyText, setNewReplyText] = useState('');

  const [selectedCategory, setSelectedCategory] = useState('Alle');
  const [search, setSearch] = useState('');

  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newTopic, setNewTopic] = useState({ title: '', category: CATEGORIES[0], content: '' });

  // Threads laden
  useEffect(() => {
    const q = query(collection(db, COLLECTIONS.THREADS), orderBy("createdAt", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
        const data = snapshot.docs.map(doc => {
            const d = doc.data();
            return {
                id: doc.id,
                ...d,
                date: d.createdAt ? new Date(d.createdAt.toDate()).toLocaleDateString('de-DE') : 'Neu'
            } as ForumThread;
        });
        setThreads(data);
    });
    return () => unsubscribe();
  }, []);

  // Antworten für gewählten Thread laden
  useEffect(() => {
    if (!selectedThread) {
      setReplies([]);
      return;
    }

    setRepliesLoading(true);
    // WICHTIG: Kein orderBy hier, um Composite Index Fehler zu vermeiden
    const q = query(
      collection(db, COLLECTIONS.REPLIES), 
      where("threadId", "==", selectedThread.id)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      } as ForumReply));

      // Sortierung clientseitig nach Zeitstempel
      const sortedReplies = data.sort((a, b) => {
        const timeA = a.createdAt?.seconds || 0;
        const timeB = b.createdAt?.seconds || 0;
        return timeA - timeB;
      });

      setReplies(sortedReplies);
      setRepliesLoading(false);
    }, (error) => {
      console.error("Firestore Error in Replies:", error);
      setRepliesLoading(false);
    });

    // View Counter erhöhen
    updateDoc(doc(db, COLLECTIONS.THREADS, selectedThread.id), {
      views: increment(1)
    });

    return () => unsubscribe();
  }, [selectedThread]);

  const handleCreateThread = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    try {
        await addDocument(COLLECTIONS.THREADS, {
            title: newTopic.title,
            author: user.name,
            authorId: user.id,
            category: newTopic.category,
            content: newTopic.content,
            replies: 0,
            views: 0
        });
        setIsCreateModalOpen(false);
        setNewTopic({ title: '', category: CATEGORIES[0], content: '' });
    } catch (err) { console.error(err); }
  };

  const handlePostReply = async () => {
    if (!user || !selectedThread || !newReplyText.trim()) return;
    try {
      await addDocument(COLLECTIONS.REPLIES, {
        threadId: selectedThread.id,
        author: user.name,
        authorId: user.id,
        content: newReplyText
      });
      await updateDoc(doc(db, COLLECTIONS.THREADS, selectedThread.id), {
        replies: increment(1),
        lastActivity: new Date()
      });
      setNewReplyText('');
    } catch (err) { console.error(err); }
  };

  const filteredThreads = threads.filter(t => {
    const matchesCategory = selectedCategory === 'Alle' || t.category === selectedCategory;
    const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="bg-slate-50 min-h-screen py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Thread Detail Modal */}
        {selectedThread && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/90 backdrop-blur-xl animate-fade-in">
             <div className="bg-white w-full max-w-5xl max-h-[95vh] rounded-[4rem] shadow-2xl flex flex-col overflow-hidden animate-fade-in-up">
                <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                   <div className="flex items-center gap-6">
                     <div className="w-16 h-16 rounded-3xl bg-indigo-600 flex items-center justify-center text-white font-black text-2xl">
                        {selectedThread.author[0]}
                     </div>
                     <div>
                       <div className="flex items-center gap-3 mb-1">
                          <span className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em] bg-indigo-50 px-3 py-1 rounded-full">
                            {selectedThread.category}
                          </span>
                       </div>
                       <h2 className="text-3xl font-black text-slate-900 tracking-tighter">{selectedThread.title}</h2>
                     </div>
                   </div>
                   <button onClick={() => setSelectedThread(null)} className="w-14 h-14 flex items-center justify-center hover:bg-slate-200 rounded-full transition-all">
                      <svg className="w-8 h-8 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                   </button>
                </div>

                <div className="flex-1 overflow-y-auto p-12 space-y-12 custom-scrollbar">
                   <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100/50 shadow-inner">
                      <div className="flex justify-between items-center mb-6">
                         <span className="text-sm font-black text-slate-900">{selectedThread.author}</span>
                         <span className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">{selectedThread.date}</span>
                      </div>
                      <p className="text-xl text-slate-700 leading-relaxed font-medium whitespace-pre-wrap">{selectedThread.content}</p>
                   </div>

                   <div className="relative py-4 flex items-center">
                      <div className="flex-grow border-t border-slate-100"></div>
                      <span className="flex-shrink mx-6 text-[11px] font-black text-slate-300 uppercase tracking-[0.3em]">
                        {repliesLoading ? 'Lade Antworten...' : `${replies.length} Antworten`}
                      </span>
                      <div className="flex-grow border-t border-slate-100"></div>
                   </div>

                   <div className="space-y-8">
                      {repliesLoading ? (
                        <div className="flex flex-col items-center py-10 gap-4">
                           <div className="w-10 h-10 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                           <span className="text-xs font-black text-slate-300 uppercase tracking-widest">Diskussion wird geladen</span>
                        </div>
                      ) : replies.length === 0 ? (
                        <div className="text-center py-10 opacity-30 italic font-medium text-slate-400">Keine Antworten vorhanden.</div>
                      ) : (
                        replies.map(reply => (
                          <div key={reply.id} className="flex gap-6 animate-fade-in group">
                             <div className="w-12 h-12 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-500 font-black shrink-0 border border-slate-200">
                               {reply.author[0]}
                             </div>
                             <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex-1 group-hover:shadow-md transition-all">
                                <div className="flex justify-between mb-4">
                                   <span className="text-sm font-black text-slate-800">{reply.author}</span>
                                   <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">
                                     {reply.createdAt ? new Date(reply.createdAt.toDate()).toLocaleDateString('de-DE') : 'Gerade jetzt'}
                                   </span>
                                </div>
                                <p className="text-slate-600 text-lg leading-relaxed font-medium">{reply.content}</p>
                             </div>
                          </div>
                        ))
                      )}
                   </div>
                </div>

                <div className="p-10 border-t border-slate-50 bg-white">
                   <div className="max-w-4xl mx-auto flex items-end gap-6">
                      <textarea 
                        value={newReplyText}
                        onChange={(e) => setNewReplyText(e.target.value)}
                        placeholder="Antwort verfassen..."
                        className="flex-1 bg-slate-50 border-0 rounded-[2rem] px-8 py-6 text-slate-900 ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 transition-all resize-none font-medium h-20 min-h-[80px] focus:h-40"
                      />
                      <button 
                        onClick={handlePostReply}
                        disabled={!newReplyText.trim() || repliesLoading}
                        className="bg-slate-900 text-white px-10 h-20 rounded-[2rem] font-black uppercase text-xs tracking-[0.2em] shadow-2xl hover:bg-indigo-600 disabled:opacity-20 transition-all active:scale-95"
                      >
                        Senden
                      </button>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* Forum Feed UI */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 gap-6">
          <div>
            <h1 className="text-5xl font-black text-slate-900 mb-3 tracking-tighter">Community Hub</h1>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Exklusiver Austausch für Immobilienprofis</p>
          </div>
          <button 
            onClick={() => setIsCreateModalOpen(true)}
            className="bg-indigo-600 text-white px-10 py-5 rounded-3xl font-black shadow-2xl hover:bg-indigo-700 transition-all active:scale-95 flex items-center gap-3 uppercase text-xs tracking-[0.2em]"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
            Neuer Thread
          </button>
        </div>

        <div className="grid lg:grid-cols-12 gap-10">
          <div className="lg:col-span-3 space-y-8">
            <div className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100">
              <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-8">Kategorien</h3>
              <div className="space-y-3">
                <button onClick={() => setSelectedCategory('Alle')} className={`w-full text-left px-6 py-4 rounded-2xl text-sm font-black transition-all ${selectedCategory === 'Alle' ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50'}`}>Alle Themen</button>
                {CATEGORIES.map(cat => (
                  <button key={cat} onClick={() => setSelectedCategory(cat)} className={`w-full text-left px-6 py-4 rounded-2xl text-sm font-black transition-all ${selectedCategory === cat ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50'}`}>{cat}</button>
                ))}
              </div>
            </div>
          </div>

          <div className="lg:col-span-9 space-y-6">
            <div className="bg-white p-3 rounded-[2.5rem] border border-slate-100 shadow-sm flex items-center gap-4">
                <div className="flex-1 flex items-center px-6 gap-4">
                    <svg className="w-6 h-6 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    <input type="text" placeholder="Beiträge durchsuchen..." className="w-full bg-transparent border-none focus:ring-0 text-lg font-bold placeholder-slate-300" value={search} onChange={(e) => setSearch(e.target.value)} />
                </div>
            </div>

            <div className="grid gap-6">
              {filteredThreads.map(thread => (
                <div key={thread.id} onClick={() => setSelectedThread(thread)} className="group bg-white p-10 rounded-[3rem] border border-slate-100 hover:border-indigo-200 transition-all cursor-pointer shadow-sm hover:shadow-2xl hover:-translate-y-1 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-2 h-full bg-slate-50 group-hover:bg-indigo-600 transition-colors"></div>
                  <div className="flex justify-between items-start gap-8">
                    <div className="flex-1">
                      <div className="flex items-center gap-4 mb-4">
                        <span className="bg-indigo-50 text-indigo-600 text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-widest">{thread.category}</span>
                        <span className="text-[10px] text-slate-300 font-black uppercase tracking-widest">{thread.date}</span>
                      </div>
                      <h3 className="text-2xl font-black text-slate-900 group-hover:text-indigo-600 transition-colors mb-4 tracking-tighter">{thread.title}</h3>
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-slate-100 rounded-xl flex items-center justify-center text-[11px] font-black text-slate-400 uppercase border border-slate-100">{thread.author[0]}</div>
                        <span className="text-xs font-black text-slate-400">Gepostet von {thread.author}</span>
                      </div>
                    </div>
                    <div className="flex gap-6 text-center">
                      <div className="px-6 py-3 bg-slate-50 rounded-2xl border border-slate-100 group-hover:bg-indigo-50 group-hover:border-indigo-100 transition-all">
                        <p className="text-xl font-black text-slate-900 group-hover:text-indigo-600">{thread.replies}</p>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Replies</p>
                      </div>
                      <div className="px-6 py-3 bg-slate-50 rounded-2xl border border-slate-100">
                        <p className="text-xl font-black text-slate-900">{thread.views}</p>
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Views</p>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {isCreateModalOpen && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fade-in">
           <div className="bg-white w-full max-w-3xl rounded-[4rem] p-16 shadow-2xl">
              <h2 className="text-4xl font-black mb-10 tracking-tighter">Neuer Beitrag</h2>
              <form onSubmit={handleCreateThread} className="space-y-8">
                <input required placeholder="Was ist Ihr Thema?" className="w-full p-6 bg-slate-50 border-0 rounded-[2rem] font-bold text-xl ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 outline-none transition-all" value={newTopic.title} onChange={e => setNewTopic({...newTopic, title: e.target.value})} />
                <textarea required placeholder="Beschreiben Sie Ihr Anliegen im Detail..." className="w-full h-56 p-8 bg-slate-50 border-0 rounded-[2.5rem] font-medium text-lg ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 outline-none transition-all" value={newTopic.content} onChange={e => setNewTopic({...newTopic, content: e.target.value})} />
                <div className="flex gap-6">
                   <button type="button" onClick={() => setIsCreateModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-500 rounded-[2rem] font-black uppercase tracking-widest text-xs">Abbrechen</button>
                   <button type="submit" className="flex-1 py-6 bg-slate-900 text-white rounded-[2rem] font-black uppercase tracking-widest text-xs shadow-2xl hover:bg-indigo-600 transition-all">Veröffentlichen</button>
                </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default Forum;

import React, { useState, useContext, useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { AuthContext } from '../App';
import { analyzePropertyRequirement } from '../services/geminiService';
import { createInquiry } from '../services/dataService';

const Wizard = () => {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    city: searchParams.get('city') || '',
    units: 10,
    propertyType: 'WEG',
    servicesNeeded: [] as string[],
    buildingAge: '',
    condition: '',
    description: '',
  });

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const analysis = await analyzePropertyRequirement(formData);

      await createInquiry({
        ...formData,
        ownerId: user?.id || 'gast',
        ownerName: user?.name || 'Gast',
        ownerEmail: user?.email || 'gast@example.de',
        status: 'neu',
        aiAnalysis: analysis,
        units: Number(formData.units),
        propertyType: formData.propertyType as any,
      });
      setTimeout(() => navigate(`/search-results?city=${encodeURIComponent(formData.city)}`), 3000);
    } catch (e) {
      console.error(e);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-[80vh] flex flex-col items-center justify-center p-8">
        <div className="w-full max-w-2xl bg-slate-900 rounded-[2rem] p-8 shadow-2xl font-mono text-indigo-400 overflow-hidden relative">
           <div className="flex gap-2 mb-6">
              <div className="w-3 h-3 rounded-full bg-red-500"></div>
              <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
              <div className="w-3 h-3 rounded-full bg-green-500"></div>
           </div>
           <div className="space-y-2 text-sm">
              <p className="animate-pulse">{">>"} INITIALIZING HAUSMATCH ENGINE...</p>
              <p className="opacity-60">{">>"} ANALYZING PROPERTY DATA FOR: {formData.city.toUpperCase()}</p>
              <p className="opacity-60">{">>"} QUERYING GOOGLE GROUNDING API...</p>
              <p className="opacity-80">{">>"} GENERATING EFFORT SCORE FOR {formData.units} UNITS...</p>
              <p className="text-white font-bold">{">>"} ANALYSING GERMAN WEG COMPLIANCE...</p>
              <div className="flex gap-1 mt-4">
                 {[1,2,3,4,5,6].map(i => (
                   <div key={i} className="h-1 flex-1 bg-indigo-500 animate-pulse" style={{animationDelay: `${i*200}ms`}}></div>
                 ))}
              </div>
           </div>
        </div>
        <p className="mt-8 text-slate-500 font-black uppercase tracking-widest animate-bounce">KI wird berechnet...</p>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-6 py-20">
      <div className="text-center mb-16">
        <h1 className="text-4xl font-black text-slate-900 tracking-tighter mb-4">Objekt-Konfigurator</h1>
        <div className="flex justify-center gap-3">
          {[0,1,2].map(i => (
            <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${step === i ? 'w-12 bg-indigo-600' : 'w-4 bg-slate-200'}`}></div>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 animate-fade-in-up">
        {step === 0 && (
          <div className="space-y-10">
            <h2 className="text-2xl font-black text-slate-800">Basis-Informationen</h2>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-4">Stadt</label>
                  <input 
                    type="text" 
                    value={formData.city} 
                    onChange={e => setFormData({...formData, city: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-2xl px-6 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all font-bold placeholder-slate-400"
                  />
               </div>
               <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-4">Anzahl Einheiten</label>
                  <input 
                    type="number" 
                    value={formData.units} 
                    onChange={e => setFormData({...formData, units: Number(e.target.value)})}
                    className="w-full bg-slate-50 border-0 rounded-2xl px-6 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all font-bold placeholder-slate-400"
                  />
               </div>
            </div>
          </div>
        )}

        {step === 1 && (
          <div className="space-y-10">
            <h2 className="text-2xl font-black text-slate-800">Objekt-Spezifikationen</h2>
            <div className="grid md:grid-cols-2 gap-8">
               <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-4">Objekttyp</label>
                  <select 
                    value={formData.propertyType}
                    onChange={e => setFormData({...formData, propertyType: e.target.value as any})}
                    className="w-full bg-slate-50 border-0 rounded-2xl px-6 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all font-bold"
                  >
                    <option value="WEG">WEG (Wohnungseigentum)</option>
                    <option value="Mietshaus">Mietshaus (Globalobjekt)</option>
                    <option value="Gewerbe">Gewerbeimmobilie</option>
                  </select>
               </div>
               <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-4">Baujahr (Ca.)</label>
                  <input 
                    type="text" 
                    value={formData.buildingAge} 
                    onChange={e => setFormData({...formData, buildingAge: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-2xl px-6 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all font-bold placeholder-slate-400"
                    placeholder="z.B. 1980"
                  />
               </div>
               <div className="space-y-2 md:col-span-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-4">Zustand des Objekts</label>
                  <select 
                    value={formData.condition}
                    onChange={e => setFormData({...formData, condition: e.target.value})}
                    className="w-full bg-slate-50 border-0 rounded-2xl px-6 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all font-bold"
                  >
                    <option value="">Zustand wählen...</option>
                    <option value="Sehr gut / Saniert">Sehr gut / Saniert</option>
                    <option value="Gepflegt">Gepflegt</option>
                    <option value="Renovierungsbedürftig">Renovierungsbedürftig</option>
                    <option value="Sanierungsstau">Sanierungsstau</option>
                  </select>
               </div>
            </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-10">
            <h2 className="text-2xl font-black text-slate-800">Bedarfs-Analyse (KI-Input)</h2>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-4">Freitext-Beschreibung</label>
              <textarea 
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
                rows={6}
                className="w-full bg-slate-50 border-0 rounded-[2rem] px-8 py-6 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-500 transition-all font-bold resize-none placeholder-slate-400"
                placeholder="Beschreiben Sie Besonderheiten, Probleme oder Wünsche an die neue Verwaltung..."
              />
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2 ml-4">Tipp: Je detaillierter, desto besser der KI-Match.</p>
            </div>
          </div>
        )}

        <div className="mt-16 flex justify-between pt-10 border-t border-slate-50">
          <button 
            onClick={() => setStep(s => s - 1)} 
            disabled={step === 0}
            className="px-8 py-4 rounded-2xl text-slate-400 font-black uppercase text-xs tracking-widest hover:text-slate-900 disabled:opacity-0 transition-all"
          >
            Zurück
          </button>
          {step < 2 ? (
            <button onClick={() => setStep(s => s + 1)} className="px-10 py-4 bg-slate-900 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-slate-900/20 hover:scale-[1.05] transition-all">
              Weiter
            </button>
          ) : (
            <button onClick={handleSubmit} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl shadow-indigo-200 hover:bg-indigo-700 hover:scale-[1.05] transition-all">
              Matches Finden
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default Wizard;

import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { loginUser, registerUser } from '../services/dataService';
import { UserRole } from '../types';

const Login = () => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);

  // States
  const [view, setView] = useState<'login' | 'role_select' | 'register_form'>('login');
  const [role, setRole] = useState<UserRole>('seeker');

  // Form Data
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [bio, setBio] = useState('');
  const [avatar, setAvatar] = useState<string>('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Image upload handler
  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) {
        setError('Das Bild ist zu groß. Bitte wählen Sie ein Bild unter 1MB.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setAvatar(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const user = await loginUser(email, password);
      if (user.role === 'manager') {
        navigate('/dashboard');
      } else {
        navigate('/wizard');
      }
    } catch (err: any) {
      setError('E-Mail oder Passwort ungültig.');
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await registerUser(email, password, name, role, avatar, bio);
      if (role === 'manager') {
        navigate('/dashboard');
      } else {
        navigate('/wizard');
      }
    } catch (err: any) {
      if (err.code === 'auth/email-already-in-use') {
        setError('Diese E-Mail-Adresse wird bereits verwendet.');
      } else if (err.code === 'auth/weak-password') {
        setError('Das Passwort sollte mindestens 6 Zeichen lang sein.');
      } else {
        setError('Registrierung fehlgeschlagen. Bitte versuchen Sie es erneut.');
      }
    } finally {
      setLoading(false);
    }
  };

  if (view === 'role_select') {
    return (
      <div className="min-h-[calc(100vh-4rem)] flex flex-col items-center justify-center py-12 px-4 relative overflow-hidden bg-slate-50">
         <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
            <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-300 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-pulse"></div>
            <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-purple-300 rounded-full mix-blend-multiply filter blur-3xl opacity-20 animate-pulse" style={{animationDelay: '2s'}}></div>
        </div>

        <div className="text-center mb-12 animate-fade-in">
            <h2 className="text-4xl font-black text-slate-900 mb-3 tracking-tight">HausMatch beitreten</h2>
            <p className="text-slate-500 font-medium text-lg">Wählen Sie Ihre Rolle auf der Plattform</p>
        </div>

        <div className="grid md:grid-cols-2 gap-8 w-full max-w-4xl px-4">
            <div 
                onClick={() => { setRole('seeker'); setView('register_form'); }}
                className="group relative bg-white rounded-[2.5rem] shadow-xl hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 overflow-hidden border border-slate-100 cursor-pointer p-10 flex flex-col items-center text-center"
            >
                <div className="absolute top-0 left-0 w-full h-2 bg-indigo-600"></div>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center text-indigo-600 mb-6 group-hover:scale-110 transition-transform duration-500 group-hover:bg-indigo-600 group-hover:text-white">
                     <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-3">Immobilieneigentümer</h3>
                <p className="text-slate-500 font-medium leading-relaxed">Finden Sie die perfekte Hausverwaltung für Ihr Objekt oder Ihre WEG.</p>
                <div className="mt-8 flex items-center text-indigo-600 font-bold gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <span>Jetzt anfangen</span>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                </div>
            </div>

            <div 
                onClick={() => { setRole('manager'); setView('register_form'); }}
                className="group relative bg-slate-900 rounded-[2.5rem] shadow-xl hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 overflow-hidden border border-slate-800 cursor-pointer p-10 flex flex-col items-center text-center"
            >
                 <div className="absolute top-0 left-0 w-full h-2 bg-indigo-500"></div>
                <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center text-indigo-400 mb-6 group-hover:scale-110 transition-transform duration-500 group-hover:bg-indigo-500 group-hover:text-white">
                     <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>
                </div>
                <h3 className="text-2xl font-black text-white mb-3">Hausverwaltung</h3>
                <p className="text-slate-400 font-medium leading-relaxed">Gewinnen Sie neue Mandate und digitalisieren Sie Ihr Lead-Management.</p>
                <div className="mt-8 flex items-center text-indigo-400 font-bold gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <span>Partner werden</span>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                </div>
            </div>
        </div>

        <button onClick={() => setView('login')} className="mt-12 text-slate-500 hover:text-indigo-600 font-bold transition-colors flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            Bereits ein Konto? Zum Login
        </button>
      </div>
    );
  }

  const isLogin = view === 'login';

  return (
    <div className="min-h-[calc(100vh-4rem)] flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8 relative overflow-hidden bg-slate-50">
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
          <div className="absolute top-20 right-20 w-96 h-96 bg-indigo-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"></div>
          <div className="absolute bottom-20 left-20 w-96 h-96 bg-blue-200 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse" style={{animationDelay: '1s'}}></div>
      </div>

      <div className={`w-full ${!isLogin ? 'max-w-3xl' : 'max-w-lg'} bg-white/80 backdrop-blur-xl rounded-[2.5rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] border border-white p-8 sm:p-12 relative animate-fade-in-up transition-all duration-700`}>
        <div className={`absolute top-0 left-0 w-full h-2 ${isLogin ? 'bg-slate-900' : 'bg-gradient-to-r from-indigo-600 to-purple-600'}`}></div>

        <div className="text-center mb-10">
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">
                {isLogin ? 'Willkommen zurück' : `${role === 'manager' ? 'Verwalter-Profil' : 'Eigentümer-Profil'} erstellen`}
            </h2>
            <p className="text-slate-500 font-medium mt-2">
                {isLogin ? 'Loggen Sie sich ein, um fortzufahren' : 'Vervollständigen Sie Ihre Angaben'}
            </p>
        </div>

        {error && (
            <div className="mb-6 p-4 bg-red-50 text-red-700 text-sm font-bold rounded-2xl flex items-center gap-3 border border-red-100 animate-shake">
                <svg className="w-5 h-5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {error}
            </div>
        )}

        <form onSubmit={isLogin ? handleLogin : handleRegister} className="space-y-6">
            {!isLogin && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start mb-8">
                    <div className="space-y-6">
                        <div className="flex flex-col items-center">
                            <div className="relative group">
                                <div className="w-28 h-28 rounded-3xl bg-slate-100 border-4 border-white shadow-xl flex items-center justify-center overflow-hidden cursor-pointer transition-transform group-hover:scale-105" onClick={() => fileInputRef.current?.click()}>
                                    {avatar ? (
                                        <img src={avatar} alt="Profile" className="w-full h-full object-cover" />
                                    ) : (
                                        <svg className="w-10 h-10 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
                                    )}
                                </div>
                                <button type="button" onClick={() => fileInputRef.current?.click()} className="absolute -bottom-2 -right-2 bg-indigo-600 shadow-xl p-2 rounded-xl text-white hover:bg-indigo-700 transition-all">
                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                                </button>
                                <input type="file" ref={fileInputRef} onChange={handleImageChange} className="hidden" accept="image/*" />
                            </div>
                            <span className="text-[10px] text-slate-400 mt-3 uppercase font-black tracking-[0.2em]">Profilbild</span>
                        </div>
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Vollständiger Name / Firma</label>
                            <input
                                required
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-600 transition-all font-bold placeholder-slate-400"
                                placeholder="Max Mustermann"
                            />
                        </div>
                    </div>
                    <div className="space-y-6 h-full flex flex-col">
                        <div className="flex-1">
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Kurzbeschreibung</label>
                            <textarea
                                value={bio}
                                onChange={(e) => setBio(e.target.value)}
                                className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-600 transition-all resize-none h-full min-h-[200px] font-bold placeholder-slate-400"
                                placeholder={role === 'manager' ? "Z.B. Spezialisiert auf WEG-Verwaltung in Berlin..." : "Z.B. Suche Verwaltung für mein Zinshaus..."}
                            />
                        </div>
                    </div>
                </div>
            )}

            <div className={`grid ${!isLogin ? 'grid-cols-1 md:grid-cols-2' : 'grid-cols-1'} gap-6`}>
                <div className="group">
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">E-Mail-Adresse</label>
                    <input
                        required
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-600 transition-all font-bold placeholder-slate-400"
                        placeholder="name@beispiel.de"
                    />
                </div>

                <div className="group">
                    <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Passwort</label>
                    <input
                        required
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className="w-full bg-slate-50 border-0 rounded-2xl px-5 py-4 text-black ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-600 transition-all font-bold placeholder-slate-400"
                        placeholder="••••••••"
                        minLength={6}
                    />
                </div>
            </div>

            <button
                type="submit"
                disabled={loading}
                className={`w-full py-5 rounded-2xl text-white font-black uppercase text-sm tracking-widest shadow-xl transition-all hover:scale-[1.02] active:scale-[0.98] disabled:opacity-70 disabled:hover:scale-100 ${
                    isLogin 
                    ? 'bg-slate-900 shadow-slate-900/20 hover:bg-slate-800' 
                    : 'bg-gradient-to-r from-indigo-600 to-purple-600 shadow-indigo-600/30 hover:shadow-indigo-600/50'
                }`}
            >
                {loading ? (
                    <span className="flex items-center justify-center gap-3">
                        <svg className="animate-spin h-5 w-5 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                        Wird verarbeitet...
                    </span>
                ) : (isLogin ? 'Anmelden' : 'Konto erstellen')}
            </button>
        </form>

        <div className="mt-10 text-center pt-8 border-t border-slate-50">
            {isLogin ? (
                <p className="text-slate-600 font-medium">
                    Noch kein Konto?{' '}
                    <button onClick={() => setView('role_select')} className="font-black text-indigo-600 hover:text-indigo-500 underline decoration-2 underline-offset-4">
                        Kostenlos registrieren
                    </button>
                </p>
            ) : (
                <p className="text-slate-600 font-medium">
                    Schon registriert?{' '}
                    <button onClick={() => setView('login')} className="font-black text-indigo-600 hover:text-indigo-500 underline decoration-2 underline-offset-4">
                        Zum Login
                    </button>
                </p>
            )}
        </div>
      </div>
    </div>
  );
};

export default Login;

export type UserRole = 'seeker' | 'manager';

export interface User {
  id: string;
  email: string;
  name: string;
  role: UserRole;
  avatar?: string;
  bio?: string;
  // Neue Profil-Felder
  location?: string;
  specialization?: string[]; // Für Verwalter: WEG, Miet, Gewerbe
  experienceYears?: number;
  phone?: string;
  website?: string;
  friends?: string[]; // Liste von User-IDs
  pendingFriends?: string[];
}

export interface Inquiry {
  id: string;
  ownerId: string;
  ownerName: string;
  ownerEmail: string;
  city: string;
  units: number;
  propertyType: 'WEG' | 'Mietshaus' | 'Gewerbe';
  servicesNeeded: string[];
  buildingAge: string;
  condition: string;
  description: string;
  status: 'neu' | 'kontaktiert' | 'archiviert' | 'offen' | 'claimed' | 'closed';
  createdAt: any;
  aiAnalysis?: InquiryAnalysis;
}

export interface InquiryAnalysis {
  summary: string;
  keyRequirements: string[];
  estimatedEffort: 'Niedrig' | 'Mittel' | 'Hoch';
  recommendedTags: string[];
  legalAdviceSnippet: string;
}

export interface ForumThread {
  id: string;
  title: string;
  content: string;
  author: string;
  authorId: string;
  category: string;
  replies: number;
  views: number;
  createdAt: any;
  lastActivity?: any;
  hasRead?: boolean;
  date?: string;
}

export interface ForumReply {
  id: string;
  threadId: string;
  author: string;
  authorId: string;
  content: string;
  createdAt: any;
}

export interface Message {
  id: string;
  senderId: string;
  senderName: string;
  receiverId: string;
  receiverName: string;
  subject: string;
  content: string;
  timestamp: any;
  read: boolean;
  isRead?: boolean;
}

export interface ManagerSearchResult {
  introText: string;
  sources: { title: string; url: string }[];
}

export interface BlogArticle {
  id: string;
  title: string;
  summary: string;
  fullContent: string;
  category: "Recht" | "Technik" | "Management" | "News";
  date: string;
  isLatest: boolean;
  sources?: { title: string; url: string }[];
}

import { User, UserRole, Inquiry, ForumThread, Message } from "../types";
import { auth, db } from "./firebase";
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signOut,
} from "firebase/auth";
import { 
  collection,
  doc,
  getDoc,
  getDocs,
  addDoc,
  setDoc,
  updateDoc,
  query,
  where,
  orderBy,
  serverTimestamp,
  arrayUnion,
  arrayRemove
} from "firebase/firestore";

export { auth, db };

// --- AUTHENTICATION ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  try {
    const userCredential = await signInWithEmailAndPassword(auth, email, password);
    const uid = userCredential.user.uid;
    const userDoc = await getDoc(doc(db, "users", uid));

    if (userDoc.exists()) {
      return { id: userDoc.id, ...userDoc.data() } as User;
    } else {
      return { 
        id: uid, 
        email: email, 
        name: email.split('@')[0], 
        role: 'seeker',
        friends: []
      } as User;
    }
  } catch (error) {
    throw error;
  }
};

export const logoutUser = async () => {
  await signOut(auth);
};

export const registerUser = async (email: string, password: string, name: string, role: UserRole, avatar?: string, bio?: string): Promise<User> => {
  try {
    const userCredential = await createUserWithEmailAndPassword(auth, email, password);
    const uid = userCredential.user.uid;
    const newUser: User = { 
      id: uid, 
      email, 
      name, 
      role,
      avatar: avatar || '',
      bio: bio || '',
      friends: [],
      pendingFriends: [],
      location: '',
      specialization: []
    };
    await setDoc(doc(db, "users", uid), newUser);
    return newUser;
  } catch (error) {
    throw error;
  }
};

// --- USER & NETWORKING ---

export const searchUsers = async (searchTerm: string): Promise<User[]> => {
  const querySnapshot = await getDocs(collection(db, "users"));
  const users = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User));
  if (!searchTerm) return users;
  return users.filter(u => u.name.toLowerCase().includes(searchTerm.toLowerCase()));
};

export const updateUserProfile = async (uid: string, data: Partial<User>) => {
  await updateDoc(doc(db, "users", uid), data);
};

export const addFriend = async (myUid: string, friendUid: string) => {
  await updateDoc(doc(db, "users", myUid), {
    friends: arrayUnion(friendUid)
  });
  await updateDoc(doc(db, "users", friendUid), {
    friends: arrayUnion(myUid)
  });
};

export const removeFriend = async (myUid: string, friendUid: string) => {
  await updateDoc(doc(db, "users", myUid), {
    friends: arrayRemove(friendUid)
  });
  await updateDoc(doc(db, "users", friendUid), {
    friends: arrayRemove(myUid)
  });
};

// --- INQUIRIES, FORUM, MESSAGING (Existing maintained) ---

export const createInquiry = async (inquiryData: Omit<Inquiry, 'id' | 'createdAt'>) => {
  const docRef = await addDoc(collection(db, "inquiries"), {
    ...inquiryData,
    createdAt: serverTimestamp(),
    status: inquiryData.status || 'offen' 
  });
  return docRef.id;
};

export const getInquiries = async (): Promise<Inquiry[]> => {
  const q = query(collection(db, "inquiries"), orderBy("createdAt", "desc"));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Inquiry));
};

export const updateInquiryStatus = async (inquiryId: string, newStatus: Inquiry['status']) => {
  await updateDoc(doc(db, "inquiries", inquiryId), { status: newStatus });
};

export const getMessages = async (userId: string): Promise<Message[]> => {
  const q = query(collection(db, "messages"), orderBy("timestamp", "desc"));
  const querySnapshot = await getDocs(q);
  const msgs = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Message));
  return msgs.filter(m => m.senderId === userId || m.receiverId === userId);
};

export const sendMessage = async (messageData: Omit<Message, 'id' | 'timestamp' | 'read'>) => {
  await addDoc(collection(db, "messages"), {
    ...messageData,
    timestamp: serverTimestamp(),
    read: false
  });
};

export const markMessageRead = async (messageId: string) => {
  await updateDoc(doc(db, "messages", messageId), { read: true });
};

import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../App';
import { searchUsers, addFriend, removeFriend, sendMessage } from '../services/dataService';
import { User } from '../types';
import { useNavigate } from 'react-router-dom';

const Network = () => {
  const { user } = useContext(AuthContext);
  const [searchTerm, setSearchTerm] = useState('');
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [msgText, setMsgText] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    const fetch = async () => {
      setLoading(true);
      const res = await searchUsers(searchTerm);
      setUsers(res.filter(u => u.id !== user?.id));
      setLoading(false);
    };
    const timer = setTimeout(fetch, 300);
    return () => clearTimeout(timer);
  }, [searchTerm, user?.id]);

  const handleToggleFriend = async (targetUser: User) => {
    if (!user) return;
    const isFriend = user.friends?.includes(targetUser.id);
    if (isFriend) {
      await removeFriend(user.id, targetUser.id);
    } else {
      await addFriend(user.id, targetUser.id);
    }
    // Update local state is handled via AuthContext re-fetch in real app, 
    // here we just alert to confirm action
    alert(isFriend ? "Vom Netzwerk entfernt" : "Zum Netzwerk hinzugefügt");
    window.location.reload(); 
  };

  const handleDirectMessage = async () => {
    if (!user || !selectedUser || !msgText.trim()) return;
    await sendMessage({
      senderId: user.id,
      senderName: user.name,
      receiverId: selectedUser.id,
      receiverName: selectedUser.name,
      subject: "Direktnachricht aus Netzwerk",
      content: msgText
    });
    setMsgText('');
    setSelectedUser(null);
    navigate('/messages');
  };

  return (
    <div className="bg-slate-50 min-h-screen py-12">
      <div className="max-w-7xl mx-auto px-6">
        <div className="flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
          <div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-2">Netzwerk</h1>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Vernetzen Sie sich mit Immobilienprofis</p>
          </div>
          <div className="w-full md:w-96 bg-white p-2 rounded-2xl shadow-sm border border-slate-100 flex items-center">
             <input 
              type="text" 
              placeholder="Nutzer suchen..." 
              className="flex-1 px-6 py-3 bg-transparent border-none text-black font-bold focus:ring-0 placeholder-slate-300"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
        </div>

        {loading ? (
          <div className="grid md:grid-cols-3 gap-8">
            {[1,2,3].map(i => <div key={i} className="h-64 bg-slate-200 rounded-[3rem] animate-pulse"></div>)}
          </div>
        ) : (
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {users.map(u => (
              <div key={u.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all group relative overflow-hidden">
                <div className="flex items-center gap-6 mb-8">
                   <div className="w-20 h-20 rounded-3xl bg-slate-100 flex items-center justify-center overflow-hidden border-2 border-slate-50">
                      {u.avatar ? <img src={u.avatar} className="w-full h-full object-cover" /> : <span className="text-3xl font-black text-slate-300">{u.name[0]}</span>}
                   </div>
                   <div>
                      <h3 className="text-2xl font-black text-slate-900 group-hover:text-indigo-600 transition-colors">{u.name}</h3>
                      <span className="text-[10px] font-black uppercase tracking-widest bg-slate-100 px-3 py-1 rounded-full text-slate-500">
                        {u.role === 'manager' ? 'Hausverwaltung' : 'Eigentümer'}
                      </span>
                   </div>
                </div>

                <p className="text-slate-500 font-medium line-clamp-2 mb-8 h-12">{u.bio || "Keine Beschreibung hinterlegt."}</p>

                <div className="grid grid-cols-2 gap-4">
                   <button 
                    onClick={() => handleToggleFriend(u)}
                    className={`py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-all ${user?.friends?.includes(u.id) ? 'bg-green-50 text-green-600 border border-green-100' : 'bg-slate-900 text-white'}`}
                   >
                     {user?.friends?.includes(u.id) ? 'Verbunden' : 'Vernetzen'}
                   </button>
                   <button 
                    onClick={() => setSelectedUser(u)}
                    className="py-4 bg-indigo-50 text-indigo-600 rounded-2xl font-black uppercase text-[10px] tracking-widest border border-indigo-100 hover:bg-indigo-100"
                   >
                     Nachricht
                   </button>
                </div>
              </div>
            ))}
          </div>
        )}

        {users.length === 0 && !loading && (
          <div className="text-center py-32 opacity-30 font-black uppercase tracking-widest text-slate-400">Keine Nutzer gefunden</div>
        )}
      </div>

      {/* Message Modal */}
      {selectedUser && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
           <div className="bg-white w-full max-w-xl rounded-[4rem] p-12 shadow-2xl animate-fade-in-up">
