              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Network;

import React, { useState, useEffect, createContext, useContext } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation, Link, useNavigate } from 'react-router-dom';
import { User, UserRole, Message } from './types';
import { auth, getUserProfile, logoutUser, markMessageRead, sendMessage as sendMsgService, getInquiries } from './services/dataService';
import { onAuthStateChanged } from 'firebase/auth';

import Wizard from './components/Wizard';
import Dashboard from './components/Dashboard';
import Forum from './components/Forum';
import SearchResults from './components/SearchResults';
import Login from './components/Login';
import Messaging from './components/Messaging';
import LandingHome from './components/LandingHome';
import ForManagers from './components/ForManagers';
import ForSeekers from './components/ForSeekers';
import Network from './components/Network';
import Profile from './components/Profile';
import { AboutPage, CareersPage, BlogPage, ContactPage, PricingPage, LegalPage } from './components/StaticPages';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType>({} as AuthContextType);

const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setLoading(true);
      if (firebaseUser) {
        const profile = await getUserProfile(firebaseUser.uid);
        if (profile) {
          setUser(profile);
        } else {
          setUser({
            id: firebaseUser.uid,
            email: firebaseUser.email || '',
            name: 'Nutzer',
            role: 'seeker',
            friends: []
          } as User);
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const logout = async () => {
    await logoutUser();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

const Navbar = () => {
  const { user, logout } = useContext(AuthContext);
  const location = useLocation();
  const navigate = useNavigate();

  const isActive = (path: string) => location.pathname === path ? 'text-indigo-600 bg-indigo-50/50 shadow-inner' : 'text-slate-600 hover:text-slate-900';

  return (
    <nav className="fixed top-0 w-full z-50 bg-white/80 backdrop-blur-xl border-b border-slate-100 shadow-sm h-16">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full">
        <div className="flex justify-between items-center h-full">
          <Link to="/" className="flex items-center gap-3">
            <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center text-white font-black text-sm">H</div>
            <span className="text-xl font-black tracking-tighter text-slate-900">HausMatch</span>
          </Link>

          <div className="hidden md:flex items-center space-x-2">
            <Link to="/" className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest transition-all ${isActive('/')}`}>Start</Link>
            <Link to="/network" className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest transition-all ${isActive('/network')}`}>Netzwerk</Link>

            {user && (
              <>
                <Link to="/forum" className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest transition-all ${isActive('/forum')}`}>Forum</Link>
                <Link to="/messages" className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest transition-all ${isActive('/messages')}`}>Postfach</Link>
                {user.role === 'manager' && (
                   <Link to="/dashboard" className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-widest transition-all ${isActive('/dashboard')}`}>Lead-Center</Link>
                )}
              </>
            )}

            {!user ? (
               <Link to="/login" className="ml-4 px-6 py-2 rounded-full bg-slate-900 text-white text-xs font-black uppercase tracking-widest hover:bg-slate-800 transition-all">Login</Link>
            ) : (
              <div className="flex items-center gap-4 ml-4 pl-4 border-l border-slate-100">
                <Link to="/profile" className="flex flex-col items-end group">
                    <span className="text-xs font-black text-slate-900 group-hover:text-indigo-600 transition-colors">{user.name}</span>
                    <span className="text-[9px] uppercase font-black text-indigo-600 tracking-tighter">{user.role === 'manager' ? 'Verwalter' : 'Eigentümer'}</span>
                </Link>
                <button onClick={logout} className="p-2 text-slate-400 hover:text-red-500 transition-colors">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7" /></svg>
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

const Footer = () => {
  return (
    <footer className="bg-white border-t border-slate-100 py-12">
      <div className="max-w-7xl mx-auto px-4 grid grid-cols-2 md:grid-cols-4 gap-8">
        <div>
          <h4 className="font-black text-slate-900 uppercase text-xs tracking-widest mb-4">HausMatch</h4>
          <ul className="space-y-2 text-sm text-slate-500 font-medium">
            <li><Link to="/about" className="hover:text-indigo-600">Über uns</Link></li>
            <li><Link to="/careers" className="hover:text-indigo-600">Karriere</Link></li>
            <li><Link to="/blog" className="hover:text-indigo-600">Blog</Link></li>
          </ul>
        </div>
        <div>
          <h4 className="font-black text-slate-900 uppercase text-xs tracking-widest mb-4">Service</h4>
          <ul className="space-y-2 text-sm text-slate-500 font-medium">
            <li><Link to="/contact" className="hover:text-indigo-600">Kontakt</Link></li>
            <li><Link to="/pricing" className="hover:text-indigo-600">Preise</Link></li>
            <li><Link to="/network" className="hover:text-indigo-600">Netzwerk</Link></li>
          </ul>
        </div>
        <div>
          <h4 className="font-black text-slate-900 uppercase text-xs tracking-widest mb-4">Rechtliches</h4>
          <ul className="space-y-2 text-sm text-slate-500 font-medium">
            <li><Link to="/legal/impressum" className="hover:text-indigo-600">Impressum</Link></li>
            <li><Link to="/legal/privacy" className="hover:text-indigo-600">Datenschutz</Link></li>
            <li><Link to="/legal/agb" className="hover:text-indigo-600">AGB</Link></li>
          </ul>
        </div>
        <div className="col-span-2 md:col-span-1">
          <p className="text-xs text-slate-400 font-medium leading-relaxed">
            HausMatch ist die führende Plattform für digitales Immobilienmanagement in Deutschland.
            © 2024 HausMatch GmbH.
          </p>
        </div>
      </div>
    </footer>
  );
};

const ProtectedRoute = ({ children, allowedRoles }: React.PropsWithChildren<{ allowedRoles?: UserRole[] }>) => {
  const { user, loading } = useContext(AuthContext);
  if (loading) return <div className="h-screen flex items-center justify-center font-black uppercase tracking-widest text-slate-300">Lädt...</div>;
  if (!user) return <Navigate to="/login" replace />;
  if (allowedRoles && !allowedRoles.includes(user.role)) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const AppRoutes = () => {
  const navigate = useNavigate();
  return (
    <Routes>
      <Route path="/" element={<LandingHome />} />
      <Route path="/seekers" element={<ForSeekers />} />
      <Route path="/managers" element={<ForManagers />} />
      <Route path="/about" element={<AboutPage />} />
      <Route path="/careers" element={<CareersPage />} />
      <Route path="/blog" element={<BlogPage />} />
      <Route path="/contact" element={<ContactPage />} />
      <Route path="/pricing" element={<PricingPage onNavigate={(p: any) => navigate(`/${p}`)} />} />
      <Route path="/legal/impressum" element={<LegalPage type="impressum" />} />
      <Route path="/legal/privacy" element={<LegalPage type="privacy" />} />
      <Route path="/legal/agb" element={<LegalPage type="agb" />} />

      <Route path="/login" element={<Login />} />
      <Route path="/wizard" element={<Wizard />} />
      <Route path="/search-results" element={<SearchResults />} />
      <Route path="/network" element={<Network />} />
      <Route path="/profile" element={
        <ProtectedRoute>
          <Profile />
        </ProtectedRoute>
      } />

      <Route path="/dashboard" element={
        <ProtectedRoute allowedRoles={['manager']}>
          <Dashboard />
        </ProtectedRoute>
      } />
      <Route path="/forum" element={
        <ProtectedRoute>
          <Forum />
        </ProtectedRoute>
      } />
      <Route path="/messages" element={
        <ProtectedRoute>
          <Messaging />
        </ProtectedRoute>
      } />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

const App = () => {
  return (
    <AuthProvider>
      <HashRouter>
        <div className="min-h-screen pt-16 bg-slate-50 selection:bg-indigo-100 selection:text-indigo-900 flex flex-col">
          <Navbar />
          <div className="flex-1">
            <AppRoutes />
          </div>
          <Footer />
        </div>
      </HashRouter>
    </AuthProvider>
  );
};

export default App;
export { AuthContext };

