      <Route path="/dashboard" element={
        <ProtectedRoute allowedRoles={['manager']}>
          <Dashboard />
        </ProtectedRoute>
      } />
      <Route path="/forum" element={
        <ProtectedRoute>
          <Forum />
        </ProtectedRoute>
      } />
      <Route path="/messages" element={
        <ProtectedRoute>
          <Messaging />
        </ProtectedRoute>
      } />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

const App = () => {
  return (
    <AuthProvider>
      <HashRouter>
        <div className="min-h-screen pt-16 bg-slate-50 selection:bg-indigo-100 selection:text-indigo-900 flex flex-col">
          <Navbar />
          <div className="flex-1">
            <AppRoutes />
          </div>
          <Footer />
        </div>
      </HashRouter>
    </AuthProvider>
  );
};

export default App;
