  sources?: { title: string; url: string }[];
}

import React, { useState, useContext, useRef } from 'react';
import { AuthContext } from '../App';
import { updateUserProfile } from '../services/dataService';

const DAYS = [
  { key: 'mon', label: 'Montag' },
  { key: 'tue', label: 'Dienstag' },
  { key: 'wed', label: 'Mittwoch' },
  { key: 'thu', label: 'Donnerstag' },
  { key: 'fri', label: 'Freitag' },
  { key: 'sat', label: 'Samstag' },
  { key: 'sun', label: 'Sonntag' }
];

const Profile = () => {
  const { user, refreshUser } = useContext(AuthContext);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: user?.name || '',
    bio: user?.bio || '',
    location: user?.location || '',
    phone: user?.phone || '',
    website: user?.website || '',
    avatar: user?.avatar || '',
    teamSize: user?.teamSize || 0,
    foundedYear: user?.foundedYear || 2024,
    vatId: user?.vatId || '',
    openingHours: user?.openingHours || {
      mon: '09:00 - 17:00', tue: '09:00 - 17:00', wed: '09:00 - 17:00', 
      thu: '09:00 - 17:00', fri: '09:00 - 15:00', sat: 'Geschlossen', sun: 'Geschlossen'
    }
  });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = async () => {
    if (!user) return;
    setLoading(true);
    await updateUserProfile(user.id, formData);
    await refreshUser();
    setIsEditing(false);
    setLoading(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) {
        alert("Bild ist zu groß (Max. 1MB)");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, avatar: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  if (!user) return null;

  const isManager = user.role === 'manager';

  return (
    <div className="bg-slate-50 min-h-screen py-24">
      <div className="max-w-6xl mx-auto px-6">
        <div className="bg-white rounded-[4rem] shadow-2xl overflow-hidden border border-slate-100">
           {/* Header Background */}
           <div className="bg-slate-900 h-64 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-600/20 blur-[100px] -mr-32 -mt-32"></div>
              <div className="absolute bottom-0 left-0 w-96 h-96 bg-blue-600/10 blur-[100px] -ml-32 -mb-32"></div>
              <div className="absolute -bottom-20 left-16 flex items-end gap-10">
                 <div className="w-48 h-48 rounded-[3.5rem] bg-white p-2 shadow-2xl relative group shrink-0">
                    <div className="w-full h-full rounded-[3.2rem] bg-slate-100 flex items-center justify-center overflow-hidden border-2 border-slate-50 shadow-inner">
                       {formData.avatar ? <img src={formData.avatar} className="w-full h-full object-cover" /> : <span className="text-6xl font-black text-slate-300">{formData.name[0]}</span>}
                    </div>
                    {isEditing && (
                       <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="absolute inset-0 bg-slate-900/60 rounded-[3.5rem] flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                       >
                          <svg className="w-10 h-10 text-white mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
                          <span className="text-[10px] font-black text-white uppercase tracking-widest">Logo ändern</span>
                       </button>
                    )}
                    <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                 </div>
                 <div className="pb-8 hidden md:block">
                    <h1 className="text-5xl font-black text-white tracking-tighter mb-2">{formData.name}</h1>
                    <span className="text-indigo-400 font-black uppercase text-xs tracking-widest">{isManager ? 'Zertifizierte Hausverwaltung' : 'Immobilieneigentümer'}</span>
                 </div>
              </div>
           </div>

           <div className="pt-32 px-16 pb-16">
              <div className="flex justify-between items-start mb-20">
                 <div className="md:hidden">
                    <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-2">{formData.name}</h1>
                 </div>
                 <div className="hidden md:flex gap-6">
                    {isManager && (
                      <>
                        <div className="bg-slate-50 px-6 py-3 rounded-2xl border border-slate-100">
                           <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">Team-Größe</span>
                           <span className="text-xl font-black text-slate-900">{formData.teamSize || '5+'} Pers.</span>
                        </div>
                        <div className="bg-slate-50 px-6 py-3 rounded-2xl border border-slate-100">
                           <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">Gegründet</span>
                           <span className="text-xl font-black text-slate-900">{formData.foundedYear || '2020'}</span>
                        </div>
                      </>
                    )}
                 </div>
                 <button 
                  onClick={() => isEditing ? handleSave() : setIsEditing(true)}
                  disabled={loading}
                  className={`px-12 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest transition-all shadow-2xl active:scale-95 ${isEditing ? 'bg-green-600 text-white shadow-green-100 hover:bg-green-700' : 'bg-slate-900 text-white shadow-slate-200 hover:bg-indigo-600'}`}
                 >
                   {loading ? 'Lädt...' : (isEditing ? 'Speichern' : 'Profil bearbeiten')}
                 </button>
              </div>

              {isEditing ? (
                <div className="space-y-16 animate-fade-in-up">
                   <div className="grid md:grid-cols-2 gap-12">
                      <div className="space-y-4">
                         <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-6">Name der Hausverwaltung / Eigentümer</label>
                         <input className="w-full bg-slate-50 border-0 rounded-[2rem] px-8 py-5 text-black font-bold ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 outline-none transition-all text-xl" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                      </div>
                      <div className="space-y-4">
                         <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-6">Standort (Hauptsitz)</label>
                         <input className="w-full bg-slate-50 border-0 rounded-[2rem] px-8 py-5 text-black font-bold ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 outline-none transition-all text-xl" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                      </div>
                   </div>

                   {isManager && (
                     <div className="bg-slate-50 p-12 rounded-[3.5rem] border border-slate-100 shadow-inner">
                        <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] mb-10">Geschäftszeiten & Details</h3>
                        <div className="grid grid-cols-2 lg:grid-cols-4 gap-8 mb-12">
                           {DAYS.map(day => (
                             <div key={day.key} className="space-y-2">
                                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">{day.label}</label>
                                <input 
                                  className="w-full bg-white border-0 rounded-xl px-4 py-3 text-black font-bold ring-1 ring-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none text-sm" 
                                  value={(formData.openingHours as any)[day.key]} 
                                  onChange={e => setFormData({
                                    ...formData, 
                                    openingHours: {...formData.openingHours, [day.key]: e.target.value}
                                  })} 
                                />
                             </div>
                           ))}
                        </div>
                        <div className="grid md:grid-cols-3 gap-8 pt-8 border-t border-slate-200">
                            <div className="space-y-2">
                               <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">Team-Größe (Mitarbeiter)</label>
                               <input type="number" className="w-full bg-white border-0 rounded-xl px-4 py-3 text-black font-bold ring-1 ring-slate-200" value={formData.teamSize} onChange={e => setFormData({...formData, teamSize: Number(e.target.value)})} />
                            </div>
                            <div className="space-y-2">
                               <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">Gründungsjahr</label>
                               <input type="number" className="w-full bg-white border-0 rounded-xl px-4 py-3 text-black font-bold ring-1 ring-slate-200" value={formData.foundedYear} onChange={e => setFormData({...formData, foundedYear: Number(e.target.value)})} />
                            </div>
                            <div className="space-y-2">
                               <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">USt-ID / Steuernummer</label>
                               <input className="w-full bg-white border-0 rounded-xl px-4 py-3 text-black font-bold ring-1 ring-slate-200" value={formData.vatId} onChange={e => setFormData({...formData, vatId: e.target.value})} placeholder="DE 123 456 789" />
                            </div>
                        </div>
                     </div>
                   )}

                   <div className="space-y-4">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-6">Ausführliche Beschreibung / Expertise</label>
                      <textarea className="w-full h-64 bg-slate-50 border-0 rounded-[3rem] px-10 py-8 text-black font-bold ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 outline-none resize-none transition-all text-xl shadow-inner" value={formData.bio} onChange={e => setFormData({...formData, bio: e.target.value})} />
                   </div>
                </div>
              ) : (
                <div className="grid lg:grid-cols-12 gap-20">
                   <div className="lg:col-span-8 space-y-16">
                      <section>
                         <h3 className="text-[11px] font-black text-slate-300 uppercase tracking-[0.4em] mb-8">Unternehmens-Vision</h3>
                         <p className="text-2xl text-slate-600 font-medium leading-relaxed italic">"{user.bio || "Dieses Mitglied hat noch keine ausführliche Vision hinterlegt. Kontaktieren Sie uns für Details."}"</p>
                      </section>

                      {isManager && (
                        <section className="bg-slate-50 p-12 rounded-[3.5rem] border border-slate-100 shadow-inner">
                           <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] mb-8">Geschäfts- & Telefonzeiten</h3>
                           <div className="grid grid-cols-2 md:grid-cols-4 gap-y-10 gap-x-6">
                              {DAYS.map(day => (
                                <div key={day.key} className="flex flex-col">
                                   <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{day.label}</span>
                                   <span className={`text-sm font-black ${(user.openingHours as any)?.[day.key] === 'Geschlossen' ? 'text-slate-300' : 'text-slate-900'}`}>
                                     {(user.openingHours as any)?.[day.key] || '09:00 - 17:00'}
                                   </span>
                                </div>
                              ))}
                           </div>
                        </section>
                      )}

                      <section className="grid md:grid-cols-2 gap-10">
                         <div className="p-10 bg-slate-50 rounded-[3.5rem] border border-slate-100 shadow-sm group hover:bg-white hover:shadow-xl transition-all">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Match-History</h4>
                            <div className="flex items-end gap-3">
                               <div className="text-5xl font-black text-slate-900 tracking-tighter">98%</div>
                               <span className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-1.5">Zufriedenheit</span>
                            </div>
                            <div className="mt-6 h-1 w-full bg-slate-200 rounded-full overflow-hidden">
                               <div className="h-full bg-indigo-600 w-full animate-pulse"></div>
                            </div>
                         </div>
                         <div className="p-10 bg-slate-50 rounded-[3.5rem] border border-slate-100 shadow-sm group hover:bg-white hover:shadow-xl transition-all">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Netzwerk-Stärke</h4>
