import React, { useState, useContext, useRef, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { AuthContext } from '../App';
import { updateUserProfile, getUserProfile, addFriend, removeFriend, sendMessage } from '../services/dataService';
import { User } from '../types';

const DAYS = [
  { key: 'mon', label: 'Montag' },
  { key: 'tue', label: 'Dienstag' },
  { key: 'wed', label: 'Mittwoch' },
  { key: 'thu', label: 'Donnerstag' },
  { key: 'fri', label: 'Freitag' },
  { key: 'sat', label: 'Samstag' },
  { key: 'sun', label: 'Sonntag' }
];

const Profile = () => {
  const { uid } = useParams();
  const navigate = useNavigate();
  const { user: currentUser, refreshUser } = useContext(AuthContext);

  const [profileUser, setProfileUser] = useState<User | null>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saveLoading, setSaveLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [showMsgModal, setShowMsgModal] = useState(false);
  const [msgText, setMsgText] = useState('');

  const [formData, setFormData] = useState<Partial<User>>({});
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isOwnProfile = !uid || uid === currentUser?.id;

  useEffect(() => {
    const fetchUser = async () => {
      setLoading(true);
      if (isOwnProfile) {
        if (currentUser) {
          setProfileUser(currentUser);
          setFormData({
            name: currentUser.name,
            bio: currentUser.bio || '',
            location: currentUser.location || '',
            phone: currentUser.phone || '',
            website: currentUser.website || '',
            avatar: currentUser.avatar || '',
            teamSize: currentUser.teamSize || 0,
            foundedYear: currentUser.foundedYear || 2024,
            vatId: currentUser.vatId || '',
            openingHours: currentUser.openingHours || {}
          });
        }
      } else {
        const profile = await getUserProfile(uid!);
        setProfileUser(profile);
      }
      setLoading(false);
    };
    fetchUser();
  }, [uid, currentUser, isOwnProfile]);

  const handleSave = async () => {
    if (!currentUser) return;
    setSaveLoading(true);
    await updateUserProfile(currentUser.id, formData);
    await refreshUser();
    setIsEditing(false);
    setSaveLoading(false);
  };

  const handleToggleFriend = async () => {
    if (!currentUser || !profileUser) {
      navigate('/login');
      return;
    }
    setActionLoading(true);
    const isFriend = currentUser.friends?.includes(profileUser.id);
    try {
      if (isFriend) {
        await removeFriend(currentUser.id, profileUser.id);
      } else {
        await addFriend(currentUser.id, profileUser.id);
      }
      await refreshUser();
    } catch (err) {
      console.error(err);
    } finally {
      setActionLoading(false);
    }
  };

  const handleSendDirectMessage = async () => {
    if (!currentUser || !profileUser || !msgText.trim()) return;
    await sendMessage({
      senderId: currentUser.id,
      senderName: currentUser.name,
      receiverId: profileUser.id,
      receiverName: profileUser.name,
      subject: "Direktanfrage via Profil",
      content: msgText
    });
    setMsgText('');
    setShowMsgModal(false);
    navigate('/messages');
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) {
        alert("Bild ist zu groß (Max. 1MB)");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, avatar: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-slate-50">
       <div className="w-16 h-16 border-4 border-slate-200 border-t-indigo-600 rounded-full animate-spin mb-4"></div>
       <span className="font-black text-xs uppercase tracking-[0.3em] text-slate-400">Profil wird geladen...</span>
    </div>
  );

  if (!profileUser) return (
    <div className="h-screen flex flex-col items-center justify-center bg-slate-50">
       <h1 className="text-2xl font-black text-slate-900 mb-4">Nutzer nicht gefunden</h1>
       <button onClick={() => navigate('/network')} className="px-8 py-3 bg-slate-900 text-white rounded-xl font-bold uppercase text-xs tracking-widest">Zurück zum Netzwerk</button>
    </div>
  );

  const isManager = profileUser.role === 'manager';
  const isFriend = currentUser?.friends?.includes(profileUser.id);

  return (
    <div className="bg-slate-50 min-h-screen py-24">
      <div className="max-w-6xl mx-auto px-6">
        <div className="bg-white rounded-[4rem] shadow-2xl overflow-hidden border border-slate-100">
           {/* Header Background */}
           <div className="bg-slate-900 h-64 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-600/20 blur-[100px] -mr-32 -mt-32"></div>
              <div className="absolute bottom-0 left-0 w-96 h-96 bg-blue-600/10 blur-[100px] -ml-32 -mb-32"></div>

              <div className="absolute -bottom-20 left-16 flex items-end gap-10">
                 <div className="w-48 h-48 rounded-[3.5rem] bg-white p-2 shadow-2xl relative group shrink-0">
                    <div className="w-full h-full rounded-[3.2rem] bg-slate-100 flex items-center justify-center overflow-hidden border-2 border-slate-50 shadow-inner">
                       {isEditing ? (
                         formData.avatar ? <img src={formData.avatar} className="w-full h-full object-cover" /> : <span className="text-6xl font-black text-slate-300">{formData.name?.[0]}</span>
                       ) : (
                         profileUser.avatar ? <img src={profileUser.avatar} className="w-full h-full object-cover" /> : <span className="text-6xl font-black text-slate-300">{profileUser.name[0]}</span>
                       )}
                    </div>
                    {isEditing && isOwnProfile && (
                       <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="absolute inset-0 bg-slate-900/60 rounded-[3.5rem] flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"
                       >
                          <svg className="w-10 h-10 text-white mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
                          <span className="text-[10px] font-black text-white uppercase tracking-widest">Logo ändern</span>
                       </button>
                    )}
                    <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                 </div>
                 <div className="pb-8 hidden md:block">
