                    <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-2">{isEditing ? formData.name : profileUser.name}</h1>
                 </div>

                 <div className="hidden md:flex gap-6">
                    {isManager && profileUser.teamSize && (
                      <div className="bg-slate-50 px-6 py-3 rounded-2xl border border-slate-100">
