                         <span className="text-xl font-black text-slate-900">{profileUser.foundedYear}</span>
                      </div>
                    )}
                 </div>

                 <div className="flex gap-4">
                    {isOwnProfile ? (
                      <button 
                        onClick={() => isEditing ? handleSave() : setIsEditing(true)}
                        disabled={saveLoading}
                        className={`px-10 py-5 rounded-[2rem] font-black uppercase text-xs tracking-widest transition-all shadow-2xl active:scale-95 ${isEditing ? 'bg-green-600 text-white shadow-green-100' : 'bg-slate-900 text-white shadow-slate-200 hover:bg-indigo-600'}`}
