                                 <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">USt-ID</label>
                                 <input className="w-full bg-white border-0 rounded-xl px-4 py-3 text-black font-bold ring-1 ring-slate-200" value={formData.vatId} onChange={e => setFormData({...formData, vatId: e.target.value})} placeholder="DE123456789" />
