                        <textarea className="w-full h-64 bg-slate-50 border-0 rounded-[3rem] px-10 py-8 text-black font-bold ring-1 ring-slate-100 focus:ring-2 focus:ring-indigo-600 outline-none resize-none transition-all text-xl shadow-inner" value={formData.bio} onChange={e => setFormData({...formData, bio: e.target.value})} />
