                                  const hours = (profileUser.openingHours as any)?.[day.key];
                                  if (!hours) return null;
                                  return (
                                    <div key={day.key} className="flex flex-col">
                                       <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{day.label}</span>
                                       <span className="text-sm font-black text-slate-900">{hours}</span>
