                        <section className="grid md:grid-cols-2 gap-8">
                           <div className="p-10 bg-slate-50 rounded-[3rem] border border-slate-100 shadow-sm group hover:bg-white hover:shadow-xl transition-all">
                              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Partner-Ranking</h4>
                              <div className="flex items-end gap-3">
                                 <div className="text-5xl font-black text-slate-900 tracking-tighter">1.0</div>
