                              </div>
                           </div>
                           <div className="p-10 bg-slate-50 rounded-[3rem] border border-slate-100 shadow-sm group hover:bg-white hover:shadow-xl transition-all">
                              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Expertise-Netzwerk</h4>
                              <div className="flex items-end gap-3">
                                 <div className="text-5xl font-black text-slate-900 tracking-tighter">{profileUser.friends?.length || 0}</div>
                                 <span className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-1.5">Kontakte</span>
                              </div>
                           </div>
                        </section>
                     </div>

                     {/* Sidebar Contact Data - Only if data exists */}
                     <div className="lg:col-span-4 space-y-8">
                        <div className="p-10 md:p-12 bg-white border border-slate-100 rounded-[3.5rem] shadow-xl relative overflow-hidden group">
