                                   </div>
                                   <div className="flex flex-col min-w-0">
                                      <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Region</span>
                                      <span className="text-slate-800 font-black text-lg break-words">{profileUser.location}</span>
